  flex-basis: 100%;
  display: grid;
  grid-template-columns: minmax(180px, 1fr) minmax(180px, 1fr) auto;
  align-items: end;
  gap: 8px;
  padding-top: 2px;
}

.query-drawer-custom-range[hidden] {
  display: none !important;
}

.query-drawer-custom-range label {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.query-drawer-custom-range label > span {
  color: var(--muted-soft);
  font-size: 8.5px;
  font-weight: 750;
}

.query-drawer-custom-range input {
  width: 100%;
  min-height: 32px;
  padding: 0 8px;
  border: 1px solid rgba(167, 205, 222, 0.62);
  border-radius: 7px;
  background: #FFFFFF;
  color: var(--ink-soft);
  font: inherit;
  font-size: 10px;
  outline: none;
}

.query-drawer-custom-range input:focus {
  border-color: rgba(41, 114, 169, 0.46);
  box-shadow: 0 0 0 2px rgba(46, 155, 203, 0.08);
}

.query-drawer-range-meta {
  min-width: 145px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  padding-top: 4px;
  text-align: right;
}

.query-drawer-range-meta strong {
  color: var(--ink-soft);
  font-size: 10px;
  font-weight: 800;
}

.query-drawer-range-meta span {
  color: var(--muted-soft);
  font-size: 8.5px;
  line-height: 1.35;
}

.query-drawer-tab {
  min-height: 41px;
  padding: 0 12px;
  font-size: 12px;
}

.query-drawer-tab-icon {
  width: 19px;
  height: 19px;
  font-size: 12px;
}

.query-drawer-content {
  min-height: 0;
  flex: 1;
  overflow: hidden;
  padding: 12px 14px 14px;
}

.query-drawer-section {
  height: 100%;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 4px;
  scrollbar-gutter: stable;
}

.query-drawer-section-live {
  overflow: hidden;
  padding-right: 0;
}

.query-drawer-live-grid {
  height: 100%;
  min-height: 0;
  grid-template-columns: minmax(0, 0.82fr) minmax(0, 1.18fr);
  align-items: stretch;
  gap: 12px;
}

.query-drawer-feed-panel {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.query-drawer-feed-panel > .query-drawer-panel-header,
.query-drawer-feed-toolbar {
  flex-shrink: 0;
}

.query-drawer-panel-kicker {
  font-size: 9px;
}

.query-drawer-panel-header h3 {
  font-size: 15px;
}

.query-drawer-panel-header p {
  font-size: 12px;
  line-height: 1.5;
}

.query-drawer-feed-toolbar {
  gap: 5px;
}

.query-drawer-feed-filter {
  min-height: 29px;
  padding: 0 9px;
  border: 0;
  font-family: inherit;
  font-size: 10px;
  cursor: pointer;
}

.query-drawer-feed-count {
  margin-left: auto;
  color: var(--muted-soft);
  font-size: 9.5px;
  font-weight: 700;
  white-space: nowrap;
}

.query-drawer-posts {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  align-content: start;
  grid-auto-rows: max-content;
  padding: 10px;
  scrollbar-gutter: stable;
}

.query-drawer-post {
  min-height: 0;
  overflow: hidden;
  padding: 0;
}

.query-drawer-post-head {
  align-items: center;
  padding: 11px 11px 0;
}

.query-drawer-post-author {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.query-drawer-post-identity {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.query-drawer-post-identity strong {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  overflow: hidden;
  color: var(--ink);
  font-size: 11.5px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-drawer-post-identity > span {
  min-width: 0;
  overflow: hidden;
  color: var(--muted);
  font-size: 9.5px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-drawer-post-date {
  max-width: 95px;
  font-size: 9px;
  line-height: 1.35;
  text-align: right;
  white-space: normal;
}

.query-drawer-post-copy {
  display: -webkit-box;
  margin-top: 8px;
  padding: 0 11px 10px;
  font-size: 13px;
  line-height: 1.58;
  -webkit-line-clamp: 6;
}

.query-drawer-post-media {
  position: relative;
  overflow: hidden;
  margin-top: 1px;
  border-top: 1px solid rgba(167, 205, 222, 0.24);
  border-bottom: 1px solid rgba(167, 205, 222, 0.24);
  background: #EEF3F6;
}

.query-drawer-media-strip {
  display: flex;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: x mandatory;
  scrollbar-width: thin;
}

.query-drawer-media-slide {
  position: relative;
  min-width: 100%;
  width: 100%;
  height: clamp(220px, 31vw, 410px);
  flex: 0 0 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  scroll-snap-align: start;
  background: #E9EEF2;
}

.query-drawer-media-image,
.query-drawer-media-video {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
  background: #E9EEF2;
}

.query-drawer-media-type-badge,
.query-drawer-carousel-badge {
  position: absolute;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 25px;
  padding: 0 8px;
  border-radius: 999px;
  background: rgba(28, 35, 48, 0.76);
  color: #FFFFFF;
  font-size: 8.5px;
  font-weight: 800;
  backdrop-filter: blur(5px);
}

.query-drawer-media-type-badge {
  left: 9px;
  bottom: 9px;
}

.query-drawer-carousel-badge {
  top: 9px;
  right: 9px;
}

.query-drawer-post-footer {
  align-items: center;
  margin-top: 0;
  padding: 10px 11px 11px;
  border-top: 0;
}

.query-drawer-post-metrics {
  gap: 5px;
}

.query-drawer-metric,
.query-drawer-metric:nth-child(5) {
  min-height: 26px;
  gap: 4px;
  padding: 0 7px;
  font-size: 9.5px;
}

.query-drawer-metric strong,
.query-drawer-metric:nth-child(5) strong {
  margin-left: 0;
  font-size: 10px;
}

.query-drawer-metric:nth-child(5)::before {
  content: none;
}

.query-drawer-post-link,
.drawer-stream-open {
  min-height: 30px;
  padding: 0 10px;
  font-size: 10.5px;
}

.drawer-avatar {
  position: relative;
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 36px;
  overflow: hidden;
  border: 1px solid rgba(167, 205, 222, 0.72);
  border-radius: 50%;
  background: linear-gradient(145deg, rgba(41, 114, 169, 0.12), rgba(46, 155, 203, 0.1));
}

.drawer-avatar-sm {
  width: 30px;
  height: 30px;
  flex-basis: 30px;
}

.drawer-avatar-md {
  width: 38px;
  height: 38px;
  flex-basis: 38px;
}

.drawer-avatar-lg {
  width: 56px;
  height: 56px;
  flex-basis: 56px;
}

.drawer-avatar-fallback {
  color: var(--blue);
  font-size: 12px;
  font-weight: 850;
}

.drawer-avatar img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: inherit;
  background: #FFFFFF;
}

.drawer-verified {
  width: 15px;
  height: 15px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 15px;
  border-radius: 50%;
  background: var(--blue);
  color: #FFFFFF;
  font-size: 8px;
  font-weight: 900;
  line-height: 1;
}

.query-drawer-live-side {
  min-height: 0;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 4px;
  scrollbar-gutter: stable;
}

.query-drawer-kpi-grid-three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.query-drawer-kpi-card {
  min-height: 92px;
  padding: 10px;
}

.query-drawer-kpi-card small {
  font-size: 9.5px;
}

.query-drawer-kpi-card strong {
  font-size: 22px;
}

.query-drawer-kpi-card > div > span {
  font-size: 10px;
  line-height: 1.42;
}

.query-drawer-live-observed {
  max-width: 180px;
  color: var(--muted-soft);
  font-size: 8.5px;
  line-height: 1.35;
  text-align: right;
}

.query-drawer-interaction-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
  padding: 11px;
}

.query-drawer-interaction-grid > span {
  min-width: 0;
  padding: 10px;
  border-radius: 9px;
  background: rgba(167, 205, 222, 0.09);
}

.query-drawer-interaction-grid small {
  display: block;
  color: var(--muted);
  font-size: 8.5px;
  font-weight: 700;
}

.query-drawer-interaction-grid strong {
  display: block;
  margin-top: 4px;
  color: var(--ink);
  font-size: 17px;
  font-weight: 850;
}

.query-drawer-live-card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.query-drawer-live-mini-panel,
.query-drawer-live-wide-panel {
  overflow: hidden;
}

.query-drawer-live-panel-body {
  padding: 11px;
}

.query-drawer-live-side .drawer-bar-list {
  gap: 9px;
}

.query-drawer-live-side .drawer-bar-row-head {
  margin-bottom: 5px;
}

.query-drawer-live-side .drawer-bar-row-head span,
.query-drawer-live-side .drawer-bar-row-head strong {
  font-size: 10px;
}

.query-drawer-live-side .drawer-bar-track {
  height: 7px;
}

.query-drawer-live-side .drawer-analysis-chip {
  min-height: 28px;
  padding: 0 8px;
  font-size: 9.5px;
}

.query-drawer-key-actor {
  display: flex;
  align-items: center;
  gap: 9px;
}

.query-drawer-key-actor > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.query-drawer-key-actor strong {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--ink);
  font-size: 11.5px;
  font-weight: 800;
}

.query-drawer-key-actor > div > span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 9.5px;
}

.query-drawer-key-actor small {
  margin-top: 5px;
  color: var(--muted-soft);
  font-size: 8.5px;
  line-height: 1.4;
}

.drawer-analysis-shell {
  min-height: 100%;
  padding-bottom: 4px;
}

.drawer-analysis-kicker {
  font-size: 9px;
}

.drawer-analysis-header h3 {
  font-size: 22px;
}

.drawer-analysis-header p {
  font-size: 12px;
  line-height: 1.58;
}

.drawer-stat-card > span {
  font-size: 10px;
}

.drawer-stat-card > strong {
  font-size: 22px;
}

.drawer-stat-card > small {
  font-size: 9.5px;
}

.drawer-analysis-card-head strong {
  font-size: 13px;
}

.drawer-analysis-card-head span {
  font-size: 10px;
}

.drawer-bar-row-head span,
.drawer-bar-row-head strong {
  font-size: 11px;
}

.drawer-analysis-chip {
  font-size: 10.5px;
}

.drawer-analysis-note strong {
  font-size: 12px;
}

.drawer-analysis-note p {
  font-size: 11px;
}

.drawer-actor-list,
.drawer-location-list {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.drawer-actor-row {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 12px;
  border: 1px solid rgba(167, 205, 222, 0.46);
  border-radius: 12px;
  background: #FFFFFF;
}

.drawer-actor-main {
  min-width: 0;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.drawer-actor-title {
  min-width: 0;
}

.drawer-actor-title strong {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--ink);
  font-size: 12px;
  font-weight: 800;
}

.drawer-actor-title > span {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 9.5px;
}

.drawer-actor-metrics {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
}

.drawer-actor-metrics > span {
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 8px;
  border-radius: 7px;
  background: rgba(167, 205, 222, 0.09);
  color: var(--muted);
  font-size: 9px;
}

.drawer-actor-metrics strong {
  color: var(--ink);
  font-size: 9.5px;
}

.drawer-location-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 10px;
  border-radius: 10px;
  background: rgba(167, 205, 222, 0.08);
}

.drawer-location-row > div {
  min-width: 0;
}

.drawer-location-row strong {
  display: block;
  color: var(--ink);
  font-size: 11px;
}

.drawer-location-row span {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 9.5px;
}

.drawer-source-row.with-avatar {
  grid-template-columns: auto minmax(90px, 0.45fr) minmax(0, 1fr) auto;
}

.drawer-profile-card {
  padding: 14px;
}

.drawer-profile-identity {
  display: flex;
  align-items: center;
  gap: 11px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(167, 205, 222, 0.28);
}

.drawer-profile-identity > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.drawer-profile-identity strong {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--ink);
  font-size: 13px;
  font-weight: 800;
}

.drawer-profile-identity > div > span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10px;
}

.drawer-profile-identity small {
  margin-top: 4px;
  color: var(--muted-soft);
  font-size: 9px;
}

.drawer-profile-metrics span {
  font-size: 8.5px;
}

.drawer-profile-metrics strong {
  font-size: 13px;
}

.drawer-stream-author {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.drawer-stream-body > p {
  font-size: 12px;
  line-height: 1.55;
}

@media (max-width: 1180px) {
  .query-drawer-live-grid {
    grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  }
  .query-drawer-kpi-grid-three {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .query-drawer-kpi-grid-three .query-drawer-kpi-card:last-child {
    grid-column: 1/-1;
  }
}
@media (max-width: 980px) {
  .query-drawer-content {
    overflow-y: auto;
  }
  .query-drawer-section,
  .query-drawer-section.active {
    height: auto;
    min-height: 100%;
    overflow: visible;
    padding-right: 0;
  }
  .query-drawer-live-grid {
    height: auto;
    grid-template-columns: 1fr;
  }
  .query-drawer-feed-panel {
    height: auto;
    max-height: 72vh;
  }
  .query-drawer-live-side {
    height: auto;
    overflow: visible;
    padding-right: 0;
  }
}
@media (max-width: 760px) {
  .query-drawer-commandbar {
    flex-direction: column;
  }
  .query-drawer-range-meta {
    width: 100%;
    align-items: flex-start;
    text-align: left;
  }
  .query-drawer-custom-range {
    grid-template-columns: 1fr;
  }
  .query-drawer-live-card-grid,
  .query-drawer-interaction-grid {
    grid-template-columns: 1fr 1fr;
  }
  .query-drawer-posts {
    grid-template-columns: 1fr;
  }
  .query-drawer-media-slide {
    height: min(70vh, 430px);
  }
  .drawer-actor-main {
    align-items: flex-start;
    flex-direction: column;
  }
  .drawer-actor-metrics {
    justify-content: flex-start;
  }
  .drawer-source-row.with-avatar {
    grid-template-columns: auto 1fr;
  }
  .drawer-source-row.with-avatar > span:last-child,
  .drawer-source-row.with-avatar > strong {
    grid-column: 2;
  }
}
@media (max-width: 520px) {
  .query-drawer-title-row h2 {
    font-size: 24px;
  }
  .query-drawer-tab {
    min-height: 39px;
    padding: 0 10px;
    font-size: 11px;
  }
  .query-drawer-live-card-grid,
  .query-drawer-interaction-grid,
  .query-drawer-kpi-grid-three {
    grid-template-columns: 1fr;
  }
  .query-drawer-kpi-grid-three .query-drawer-kpi-card:last-child {
    grid-column: auto;
  }
  .query-drawer-post-copy {
    font-size: 12px;
  }
}

