appsmith.onReady(function () {
  var currentPage = 1;
  var currentQueryView = 'constructor';
  var currentMode = 'home';
  var currentStep = 0;
  var groups = [];
  var selectedTargetIds = [];
  var useWeb = false;
  var lastQueriesValue = null;
  var lastTargetsValue = null;
  var lastModeValue = null;
  var lastStepValue = null;
  var lastGroupsValue = null;
  var lastTargetIdsValue = null;
  var lastUseWebValue = null;
  var lastAiResponseValue = null;
  var lastSelectedQueryIdValue = null;
  var aiRequestPending = false;
  var aiFeedbackMessage = '';
  var aiWarnings = [];
  var aiGenerateArmed = false;
  var aiGenerateInstruction = '';
  var aiDraftInstruction = null;
  var sourceSearchTimer = null;
  var lastSourceManagementValue = null;
  var pendingSaveConfirmation = null;
  var sourceUiState = {
    page: 1,
    pageSize: 25,
    search: '',
    platformFilter: '',
    statusFilter: '',
    formPlatform: '',
    formHandle: '',
    formExternalId: '',
    actionId: ''
  };
  var sourceUiStateInitialized = false;
  var drawerState = {
    open: false,
    activeSection: 'live',
    range: '12h',
    customStart: null,
    customEnd: null,
    feedSort: 'recent',
    whatTab: 'publications'
  };
  var lastDrawerPostsValue = null;
  var lastDrawerActorsValue = null;
  var drawerPostsCacheByQuery = {};
  var drawerActorsCacheByQuery = {};
  var drawerSelection = {
    id: '',
    name: '',
    query: null
  };
  var lastNonEmptyDrawerPosts = [];
  var lastNonEmptyDrawerActors = [];
  function getModel() {
    return appsmith.model || {};
  }
  function escapeHtml(value) {
    var div = document.createElement('div');
    div.textContent = value == null ? '' : String(value);
    return div.innerHTML;
  }
  function asArray(value) {
    if (Array.isArray(value)) {
      return value;
    }
    if (typeof value !== 'string' || value.trim() === '') {
      return [];
    }
    var text = value.trim();
    try {
      var parsed = JSON.parse(text);
      return Array.isArray(parsed) ? parsed : [];
    } catch (directError) {
      try {
        var decoded = decodeURIComponent(text);
        var decodedParsed = JSON.parse(decoded);
        return Array.isArray(decodedParsed) ? decodedParsed : [];
      } catch (decodedError) {
        return [];
      }
    }
  }
  function asObject(value) {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      return value;
    }
    if (typeof value !== 'string' || value.trim() === '') {
      return {};
    }
    var text = value.trim();
    try {
      var parsed = JSON.parse(text);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch (directError) {
      try {
        var decoded = decodeURIComponent(text);
        var decodedParsed = JSON.parse(decoded);
        return decodedParsed && typeof decodedParsed === 'object' && !Array.isArray(decodedParsed) ? decodedParsed : {};
      } catch (decodedError) {
        return {};
      }
    }
  }
  function normalizeTerms(value) {
    if (!Array.isArray(value)) {
      return [];
    }
    return value.map(function (term) {
      return String(term == null ? '' : term).trim();
    }).filter(function (term) {
      return term !== '';
    });
  }
  function createEmptyGroup(groupNo) {
    return {
      group_no: groupNo,
      include: [],
      and: [],
      and_not: []
    };
  }
  function normalizeGroup(group, index) {
    return {
      group_no: index + 1,
      include: normalizeTerms(group && group.include),
      and: normalizeTerms(group && group.and),
      and_not: normalizeTerms(group && group.and_not)
    };
  }
  function loadGroupsFromModel() {
    var raw = getModel().query_groups_json;
    var parsed = [];
