}

.query-drawer-kpi-card > div > span {
  font-size: 10px;
  line-height: 1.42;
}

.query-drawer-live-observed {
  max-width: 180px;
  color: var(--muted-soft);
  font-size: 8.5px;
  line-height: 1.35;
  text-align: right;
}

.query-drawer-interaction-grid {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 7px;
  padding: 11px;
}

.query-drawer-interaction-grid > span {
  min-width: 0;
  padding: 10px;
  border-radius: 9px;
  background:
    rgba(167, 205, 222, 0.09);
}

.query-drawer-interaction-grid small {
  display: block;
  color: var(--muted);
  font-size: 8.5px;
  font-weight: 700;
}

.query-drawer-interaction-grid strong {
  display: block;
  margin-top: 4px;
  color: var(--ink);
  font-size: 17px;
  font-weight: 850;
}

.query-drawer-live-card-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.query-drawer-live-mini-panel,
.query-drawer-live-wide-panel {
  overflow: hidden;
}

.query-drawer-live-panel-body {
  padding: 11px;
}

.query-drawer-live-side .drawer-bar-list {
  gap: 9px;
}

.query-drawer-live-side .drawer-bar-row-head {
  margin-bottom: 5px;
}

.query-drawer-live-side .drawer-bar-row-head span,
.query-drawer-live-side .drawer-bar-row-head strong {
  font-size: 10px;
}

.query-drawer-live-side .drawer-bar-track {
  height: 7px;
}

.query-drawer-live-side .drawer-analysis-chip {
  min-height: 28px;
  padding: 0 8px;
  font-size: 9.5px;
}

.query-drawer-key-actor {
  display: flex;
  align-items: center;
  gap: 9px;
}

.query-drawer-key-actor > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.query-drawer-key-actor strong {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--ink);
  font-size: 11.5px;
  font-weight: 800;
}

.query-drawer-key-actor > div > span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 9.5px;
}

.query-drawer-key-actor small {
  margin-top: 5px;
  color: var(--muted-soft);
  font-size: 8.5px;
  line-height: 1.4;
}

.drawer-analysis-shell {
  min-height: 100%;
  padding-bottom: 4px;
}

.drawer-analysis-kicker {
  font-size: 9px;
}

.drawer-analysis-header h3 {
  font-size: 22px;
}

.drawer-analysis-header p {
  font-size: 12px;
  line-height: 1.58;
}

.drawer-stat-card > span {
  font-size: 10px;
}

.drawer-stat-card > strong {
  font-size: 22px;
}

.drawer-stat-card > small {
  font-size: 9.5px;
}

.drawer-analysis-card-head strong {
  font-size: 13px;
}

.drawer-analysis-card-head span {
  font-size: 10px;
}

.drawer-bar-row-head span,
.drawer-bar-row-head strong {
  font-size: 11px;
}

.drawer-analysis-chip {
  font-size: 10.5px;
}

.drawer-analysis-note strong {
  font-size: 12px;
}

.drawer-analysis-note p {
  font-size: 11px;
}

.drawer-actor-list,
.drawer-location-list {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.drawer-actor-row {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 12px;
  border:
    1px solid rgba(167, 205, 222, 0.46);
  border-radius: 12px;
  background: #FFFFFF;
}

.drawer-actor-main {
  min-width: 0;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.drawer-actor-title {
  min-width: 0;
}

.drawer-actor-title strong {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--ink);
  font-size: 12px;
  font-weight: 800;
}

.drawer-actor-title > span {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 9.5px;
}

.drawer-actor-metrics {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
}

.drawer-actor-metrics > span {
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 8px;
  border-radius: 7px;
  background:
    rgba(167, 205, 222, 0.09);
  color: var(--muted);
  font-size: 9px;
}

.drawer-actor-metrics strong {
  color: var(--ink);
  font-size: 9.5px;
}

.drawer-location-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 10px;
  border-radius: 10px;
  background:
    rgba(167, 205, 222, 0.08);
}

.drawer-location-row > div {
  min-width: 0;
}

.drawer-location-row strong {
  display: block;
  color: var(--ink);
  font-size: 11px;
}

.drawer-location-row span {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 9.5px;
}

.drawer-source-row.with-avatar {
  grid-template-columns:
    auto
    minmax(90px, 0.45fr)
    minmax(0, 1fr)
    auto;
}

.drawer-profile-card {
  padding: 14px;
}

.drawer-profile-identity {
  display: flex;
  align-items: center;
  gap: 11px;
  padding-bottom: 12px;
  border-bottom:
    1px solid rgba(167, 205, 222, 0.28);
}

.drawer-profile-identity > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.drawer-profile-identity strong {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--ink);
  font-size: 13px;
  font-weight: 800;
}

.drawer-profile-identity > div > span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10px;
}

.drawer-profile-identity small {
  margin-top: 4px;
  color: var(--muted-soft);
  font-size: 9px;
}

.drawer-profile-metrics span {
  font-size: 8.5px;
}

.drawer-profile-metrics strong {
  font-size: 13px;
}

.drawer-stream-author {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.drawer-stream-body > p {
  font-size: 12px;
  line-height: 1.55;
}

@media (max-width: 1180px) {
  .query-drawer-live-grid {
    grid-template-columns:
      minmax(0, 0.9fr)
      minmax(0, 1.1fr);
  }

  .query-drawer-kpi-grid-three {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .query-drawer-kpi-grid-three
  .query-drawer-kpi-card:last-child {
    grid-column: 1 / -1;
  }
}

@media (max-width: 980px) {
  .query-drawer-content {
    overflow-y: auto;
  }

  .query-drawer-section,
  .query-drawer-section.active {
    height: auto;
    min-height: 100%;
    overflow: visible;
    padding-right: 0;
  }

  .query-drawer-live-grid {
    height: auto;
    grid-template-columns: 1fr;
  }

  .query-drawer-feed-panel {
    height: auto;
    max-height: 72vh;
  }

  .query-drawer-live-side {
    height: auto;
    overflow: visible;
    padding-right: 0;
  }
}

@media (max-width: 760px) {
  .query-drawer-commandbar {
    flex-direction: column;
  }

  .query-drawer-range-meta {
    width: 100%;
    align-items: flex-start;
    text-align: left;
  }

  .query-drawer-custom-range {
    grid-template-columns: 1fr;
  }

  .query-drawer-live-card-grid,
  .query-drawer-interaction-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .query-drawer-posts {
    grid-template-columns: 1fr;
  }

  .query-drawer-media-slide {
    height:
      min(70vh, 430px);
  }

  .drawer-actor-main {
    align-items: flex-start;
    flex-direction: column;
  }

  .drawer-actor-metrics {
    justify-content: flex-start;
  }

  .drawer-source-row.with-avatar {
    grid-template-columns:
      auto 1fr;
  }

  .drawer-source-row.with-avatar > span:last-child,
  .drawer-source-row.with-avatar > strong {
    grid-column: 2;
  }
}

@media (max-width: 520px) {
  .query-drawer-title-row h2 {
    font-size: 24px;
  }

  .query-drawer-tab {
    min-height: 39px;
    padding: 0 10px;
    font-size: 11px;
  }

  .query-drawer-live-card-grid,
  .query-drawer-interaction-grid,
  .query-drawer-kpi-grid-three {
    grid-template-columns: 1fr;
  }

  .query-drawer-kpi-grid-three
  .query-drawer-kpi-card:last-child {
    grid-column: auto;
  }

  .query-drawer-post-copy {
    font-size: 12px;
  }
}

