            sourceUiState.page = !isNaN(page) && page > 0 ? page : 1;
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourcePageSize')) {
            var pageSize = parseInt(patch.sourcePageSize, 10);
            sourceUiState.pageSize = !isNaN(pageSize) && pageSize > 0 ? Math.min(pageSize, 100) : 25;
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourceSearch')) {
            sourceUiState.search = String(patch.sourceSearch || '').trim();
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourcePlatformFilter')) {
            sourceUiState.platformFilter = String(patch.sourcePlatformFilter || '').trim();
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourceStatusFilter')) {
            sourceUiState.statusFilter = String(patch.sourceStatusFilter || '').trim();
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourceFormPlatform')) {
