        function buildGroupedOptions(items) {
            var grouped = {};
            items.forEach(function(platform) {
                var category = String(platform.category || 'Otras').trim() || 'Otras';
                if (!grouped[category]) {
                    grouped[category] = [];
                }
                grouped[category].push(platform);
            });
            return Object.keys(grouped).sort(function(a, b) {
                return a.localeCompare(b, 'es', {
                    sensitivity: 'base'
                });
            }).map(function(category) {
                var options = grouped[category].slice().sort(function(a, b) {
                    return String(a.display_name || a.code || '').localeCompare(String(b.display_name || b.code || ''), 'es', {
                        sensitivity: 'base'
                    });
                }).map(function(platform) {
                    return ('<option value="' + escapeHtml(platform.code) + '">' + escapeHtml(platform.display_name || platform.code) + '</option>');
                }).join('');
                return ('<optgroup label="' + escapeHtml(category) + '">' + options + '</optgroup>');
            }).join('');
        }
        if (formSelect) {
            var eligiblePlatforms = platforms.filter(function(platform) {
                return (platform && platform.code && toBoolean(platform.is_active));
            });
            formSelect.innerHTML = '<option value="">' + 'Selecciona plataforma' + '</option>' + buildGroupedOptions(eligiblePlatforms);
            if (eligiblePlatforms.some(function(platform) {
                    return (String(platform.code) === formValue);
                })) {
                formSelect.value = formValue;
            } else if (document.activeElement !== formSelect) {
                formSelect.value = '';
            }
        }
        if (filterSelect) {
            var filterPlatforms = platforms.filter(function(platform) {
                return (platform && platform.code);
            });
            filterSelect.innerHTML = '<option value="">' + 'Todas las plataformas' + '</option>' + buildGroupedOptions(filterPlatforms);
            filterSelect.value = filterValue;
        }
    }

