    function cacheDrawerActors(actors) {
        var sourceActors = asArray(actors);

        if (!sourceActors.length) {
            return;
        }

        lastNonEmptyDrawerActors = sourceActors.slice();

        var grouped = {};

        sourceActors.forEach(function(actor) {
            if (!actor) {
                return;
            }

            var queryId = String(actor.query_id || '').trim();

            if (!queryId) {
                return;
            }

            if (!grouped[queryId]) {
                grouped[queryId] = [];
            }

            grouped[queryId].push(actor);
        });

        Object.keys(grouped).forEach(function(queryId) {
            if (grouped[queryId].length > 0) {
                drawerActorsCacheByQuery[queryId] = grouped[queryId].slice();
            }
        });
    }

    function rememberDrawerSelection(queryId, queryName, query) {
        var id = String(queryId || '').trim();

        if (!id) {
            return;
        }

        drawerSelection.id = id;

        if (queryName !== null && queryName !== undefined) {
            drawerSelection.name = String(queryName || '').trim();
        }

        if (query && typeof query === 'object') {
            drawerSelection.query = query;
        }
    }

    function cacheDrawerPosts(posts) {
        var sourcePosts = asArray(posts);

        if (!sourcePosts.length) {
            return;
        }

        lastNonEmptyDrawerPosts = sourcePosts.slice();

        var grouped = {};

        sourcePosts.forEach(function(post) {
            if (!post) {
                return;
            }

            var queryId = String(post.query_id || '').trim();

            if (!queryId) {
                return;
            }

            if (!grouped[queryId]) {
                grouped[queryId] = [];
