            grouped[queryId].push(post);
        });

        Object.keys(grouped).forEach(function(queryId) {
            if (grouped[queryId].length > 0) {
                drawerPostsCacheByQuery[queryId] = grouped[queryId].slice();
            }
        });
    }

    function getActiveDrawerQueryId(model) {
        var drawerModel = model || getModel();

        return String(
            drawerSelection.id ||
            drawerModel.selectedQueryId ||
            ''
        ).trim();
    }

    function getSelectedQuery(model) {
        var drawerModel = model || getModel();
        var selectedId = getActiveDrawerQueryId(drawerModel);

        if (!selectedId) {
            return drawerSelection.query || null;
        }

        var query = asArray(drawerModel.queries).find(function(item) {
            return item && String(item.id || '') === selectedId;
        }) || null;

        if (query) {
            rememberDrawerSelection(
                selectedId,
                query.name || drawerSelection.name,
                query
            );
            return query;
        }

        if (
            drawerSelection.query &&
            String(drawerSelection.query.id || '') === selectedId
        ) {
            return drawerSelection.query;
        }

        return null;
    }

    function getDrawerPosts(model) {
        var drawerModel = model || getModel();
        var selectedId = getActiveDrawerQueryId(drawerModel);
        var sourcePosts = asArray(drawerModel.drawerPosts);

        if (sourcePosts.length > 0) {
            cacheDrawerPosts(sourcePosts);
        }

        if (!selectedId) {
            return sourcePosts.length > 0
                ? sourcePosts.slice()
                : lastNonEmptyDrawerPosts.slice();
        }

        var matchingPosts = sourcePosts.filter(function(post) {
            return post && String(post.query_id || '') === selectedId;
        });

        if (matchingPosts.length > 0) {
            drawerPostsCacheByQuery[selectedId] = matchingPosts.slice();
            return matchingPosts;
        }

        if (
            Object.prototype.hasOwnProperty.call(
                drawerPostsCacheByQuery,
                selectedId
            ) &&
            drawerPostsCacheByQuery[selectedId].length > 0
        ) {
            return drawerPostsCacheByQuery[selectedId].slice();
        }

        var fallback = lastNonEmptyDrawerPosts.filter(function(post) {
            return post && String(post.query_id || '') === selectedId;
        });

        if (fallback.length > 0) {
            drawerPostsCacheByQuery[selectedId] = fallback.slice();
            return fallback;
        }

        return [];
    }

