    function getDrawerRangeLabel() {
        var bounds = getDrawerRangeBounds();
        if (drawerState.range === 'all') {
            return 'Todo el histórico disponible';
        }
        if (!bounds.start || !bounds.end) {
            return 'Rango personalizado';
        }
        return formatDrawerRangeMoment(bounds.start) + ' – ' + formatDrawerRangeMoment(bounds.end);
    }

    function toDrawerLocalInputValue(value) {
        var date = value instanceof Date ? value : new Date(value);
        if (!date || isNaN(date.getTime())) {
            return '';
        }
        var pad = function(number) {
            return String(number).padStart(2, '0');
        };
        return date.getFullYear() + '-' +
            pad(date.getMonth() + 1) + '-' +
            pad(date.getDate()) + 'T' +
            pad(date.getHours()) + ':' +
            pad(date.getMinutes());
    }

    function initializeDrawerCustomRangeInputs() {
        var startInput = document.getElementById('queryDrawerRangeStart');
        var endInput = document.getElementById('queryDrawerRangeEnd');
        var end = getDrawerNow();
        var start = new Date(end.getTime() - 12 * 60 * 60 * 1000);

        if (!drawerState.customStart) {
            drawerState.customStart = start.toISOString();
        }
        if (!drawerState.customEnd) {
            drawerState.customEnd = end.toISOString();
        }
        if (startInput) {
            startInput.value = toDrawerLocalInputValue(drawerState.customStart || start);
        }
        if (endInput) {
            endInput.value = toDrawerLocalInputValue(drawerState.customEnd || end);
        }
    }

