    function getDrawerInitials(value) {
        var words = String(value || '').trim().split(/\s+/).filter(Boolean);
        if (!words.length) {
            return '•';
        }
        if (words.length === 1) {
            return words[0].slice(0, 2).toUpperCase();
        }
        return (words[0].charAt(0) + words[1].charAt(0)).toUpperCase();
    }

    function renderDrawerAvatar(url, label, sizeClass) {
        var safeUrl = safeDrawerUrl(url);
        var className = 'drawer-avatar ' + String(sizeClass || 'drawer-avatar-md');
        return (
            '<span class="' + escapeHtml(className) + '">' +
                '<span class="drawer-avatar-fallback">' + escapeHtml(getDrawerInitials(label)) + '</span>' +
                (safeUrl
                    ? '<img src="' + escapeHtml(safeUrl) + '" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display=\'none\'">'
                    : '') +
            '</span>'
        );
    }

    function renderDrawerVerified(value) {
        return drawerBoolean(value) === true
            ? '<span class="drawer-verified" title="Perfil verificado">✓</span>'
            : '';
    }

    function getDrawerLatestObservedAt(posts) {
        var latest = null;
        posts.forEach(function(post) {
            var candidate = post && (
                post.metrics_last_observed_at ||
                post.metrics_fetched_at ||
                post.scraped_at ||
                post.last_confirmed_at ||
                post.matched_at
            );
            if (!candidate) {
                return;
            }
            var time = new Date(candidate).getTime();
            if (!isNaN(time) && (latest === null || time > latest)) {
                latest = time;
            }
        });
        return latest === null ? null : new Date(latest).toISOString();
    }

    function getDrawerPlatformCounts(posts) {
        var counts = {};
        posts.forEach(function(post) {
            var platform = String(post && post.platform || '').trim().toLowerCase() || 'sin_plataforma';
            counts[platform] = (counts[platform] || 0) + 1;
        });
        var preferredOrder = ['facebook', 'instagram', 'threads'];
        return Object.keys(counts)
            .sort(function(a, b) {
                var indexA = preferredOrder.indexOf(a);
                var indexB = preferredOrder.indexOf(b);
                if (indexA === -1 && indexB === -1) {
                    return a.localeCompare(b, 'es', { sensitivity: 'base' });
                }
                if (indexA === -1) {
                    return 1;
                }
                if (indexB === -1) {
                    return -1;
                }
                return indexA - indexB;
            })
            .map(function(platform) {
                return { platform: platform, count: counts[platform] };
            });
    }

    function setDrawerSection(section) {
        var allowedSections = [
            'live', 'what', 'when', 'howmuch', 'how',
            'who', 'where', 'profiles', 'botometer', 'streams'
        ];
        var nextSection = allowedSections.indexOf(String(section || '')) !== -1 ? String(section) : 'live';
        drawerState.activeSection = nextSection;

        var drawer = document.getElementById('queryDrawer');
        if (!drawer) {
            return;
        }

        var activeControl = document.getElementById('queryDrawerTab-' + nextSection);
        if (activeControl) {
            activeControl.checked = true;
        }

        drawer.querySelectorAll('.query-drawer-tab').forEach(function(tab) {
            var isActive = tab.getAttribute('for') === 'queryDrawerTab-' + nextSection;
            tab.classList.toggle('active', isActive);
            tab.setAttribute('aria-selected', isActive ? 'true' : 'false');
        });

        drawer.querySelectorAll('[data-drawer-section-panel]').forEach(function(panel) {
            var isActive = panel.getAttribute('data-drawer-section-panel') === nextSection;
            panel.classList.toggle('active', isActive);
            panel.hidden = !isActive;
        });
    }

