    function openPostExternally(url) {
        var normalized = String(url || '').trim();
        if (!/^https?:\/\//i.test(normalized)) {
            return;
        }
        try {
            appsmith.triggerEvent('onOpenPost', { url: normalized });
        } catch (error) {
            console.error('No fue posible abrir la publicación:', error);
        }
    }

    function getDrawerSummary(posts) {
        var likes = drawerSum(posts, 'likes_count');
        var comments = drawerSum(posts, 'platform_comments_count');
        var shares = drawerSum(posts, 'shares_count');
        var views = drawerSum(posts, 'views_count');
        var storedComments = drawerSum(posts, 'stored_comments_count');
        var interactions = 0;
        var interactionsAvailable = false;

        posts.forEach(function(post) {
            var total = getDrawerInteractionTotal(post);
            if (total === null) {
                return;
            }
            interactionsAvailable = true;
            interactions += total;
        });

        return {
            posts: posts.length,
            likes: likes,
            comments: comments,
            shares: shares,
            views: views,
            storedComments: storedComments,
            interactions: interactionsAvailable ? interactions : null
        };
    }

    function getDrawerMetricCoverage(posts) {
        var metrics = [
            { key: 'likes_count', label: 'Me gusta' },
            { key: 'platform_comments_count', label: 'Comentarios' },
            { key: 'shares_count', label: 'Compartidos' },
            { key: 'views_count', label: 'Vistas' },
            { key: 'stored_comments_count', label: 'Comentarios guardados' }
        ];
        return metrics.map(function(metric) {
            var count = posts.filter(function(post) {
                return drawerNumber(post && post[metric.key]) !== null;
            }).length;
            return {
                key: metric.key,
                label: metric.label,
                count: count,
                percent: posts.length ? (count / posts.length) * 100 : 0
            };
        });
    }

    function getDrawerPostTypes(posts) {
        var counts = {};
        posts.forEach(function(post) {
            var type = String(post && post.post_type || 'sin_tipo').trim().toLowerCase() || 'sin_tipo';
            counts[type] = (counts[type] || 0) + 1;
        });
        return Object.keys(counts)
            .map(function(type) {
                return {
                    key: type,
                    label: type === 'sin_tipo' ? 'Sin tipo' : type.charAt(0).toUpperCase() + type.slice(1),
                    count: counts[type]
                };
            })
            .sort(function(a, b) {
                return b.count - a.count;
            });
    }

    function normalizeDrawerWord(value) {
        var text = String(value || '').toLowerCase();
        try {
            text = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        } catch (error) {
        }
        return text;
    }

    function getDrawerTerms(posts) {
        var stopWords = {
            para: true, pero: true, como: true, este: true, esta: true, estos: true, estas: true,
            desde: true, hasta: true, entre: true, sobre: true, todo: true, toda: true, todos: true,
            todas: true, una: true, unas: true, uno: true, unos: true, del: true, las: true, los: true,
            con: true, por: true, que: true, sus: true, son: true, fue: true, han: true, hay: true,
            muy: true, mas: true, sin: true, nuestro: true, nuestra: true, nuestros: true, nuestras: true,
            cada: true, donde: true, cuando: true, quien: true, quienes: true, tambien: true, hacia: true,
            tras: true, mediante: true, porque: true, esto: true, al: true, el: true, la: true,
            de: true, en: true, y: true, o: true, a: true, se: true, es: true
        };
        var words = {};
        var hashtags = {};

        posts.forEach(function(post) {
            var text = String(post && post.content_text || '');
            var hashtagMatches = text.match(/#[A-Za-zÀ-ÿ0-9_]+/g) || [];
            hashtagMatches.forEach(function(tag) {
                var key = tag.toLowerCase();
                if (!hashtags[key]) {
                    hashtags[key] = { label: tag, count: 0 };
                }
                hashtags[key].count += 1;
            });

            var plain = normalizeDrawerWord(text)
                .replace(/https?:\/\/\S+/g, ' ')
                .replace(/@[A-Za-z0-9_.-]+/g, ' ')
                .replace(/#[A-Za-zÀ-ÿ0-9_]+/g, ' ')
                .replace(/[^a-z0-9ñ]+/g, ' ');

            plain.split(/\s+/).forEach(function(word) {
                if (word.length < 4 || stopWords[word]) {
                    return;
                }
                words[word] = (words[word] || 0) + 1;
            });
        });

        return {
            terms: Object.keys(words)
                .map(function(word) { return { label: word, count: words[word] }; })
                .sort(function(a, b) {
                    return b.count - a.count || a.label.localeCompare(b.label, 'es');
                })
                .slice(0, 18),
            hashtags: Object.keys(hashtags)
                .map(function(key) { return hashtags[key]; })
                .sort(function(a, b) { return b.count - a.count; })
                .slice(0, 18)
        };
    }

    function getDrawerActivity(posts) {
        var byDay = {};
        var byHour = {};
        posts.forEach(function(post) {
            if (!post || !post.published_at) {
                return;
            }
            var date = new Date(post.published_at);
            if (isNaN(date.getTime())) {
                return;
            }
            var dayKey = date.getFullYear() + '-' +
                String(date.getMonth() + 1).padStart(2, '0') + '-' +
                String(date.getDate()).padStart(2, '0');
            var hour = date.getHours();
            byDay[dayKey] = (byDay[dayKey] || 0) + 1;
            byHour[hour] = (byHour[hour] || 0) + 1;
        });

        var dayItems = Object.keys(byDay).sort().map(function(dayKey) {
            var date = new Date(dayKey + 'T12:00:00');
            var label = dayKey;
            try {
                label = new Intl.DateTimeFormat('es-MX', {
                    day: '2-digit',
                    month: 'short'
                }).format(date);
            } catch (error) {
            }
            return { key: dayKey, label: label, count: byDay[dayKey] };
        });

        var hourItems = Object.keys(byHour)
            .map(function(hour) {
                var hourNumber = Number(hour);
                return {
                    key: hourNumber,
                    label: String(hourNumber).padStart(2, '0') + ':00',
                    count: byHour[hour]
                };
            })
            .sort(function(a, b) { return b.count - a.count; });

        return { days: dayItems, hours: hourItems };
    }

    function getDrawerProfiles(posts) {
        var profilesByKey = {};

        posts.forEach(function(post) {
            var platform = String(post && post.platform || 'sin_plataforma').trim().toLowerCase();
            var username = String(post && post.profile_username || post && post.handle || 'sin_handle').trim();
            var handle = username || 'sin_handle';
            var key = platform + '|' + handle.toLowerCase();

            if (!profilesByKey[key]) {
                profilesByKey[key] = {
                    platform: platform,
                    handle: handle,
                    displayName: String(post && post.profile_display_name || '').trim(),
                    avatarUrl: getDrawerAvatarUrl(post),
                    profileUrl: safeDrawerUrl(post && post.profile_url),
                    locationText: String(post && post.profile_location_text || '').trim(),
                    category: String(post && post.profile_category || '').trim(),
                    isVerified: drawerBoolean(post && post.profile_is_verified),
                    followersCount: drawerNumber(post && post.followers_count),
                    followingCount: drawerNumber(post && post.following_count),
                    profilePostsCount: drawerNumber(post && post.profile_posts_count),
                    profileFirstObservedAt: post && post.profile_first_observed_at || null,
                    profileLastObservedAt: post && post.profile_last_observed_at || null,
                    posts: 0,
                    likes: 0,
                    comments: 0,
                    shares: 0,
                    views: 0,
                    interactions: 0,
                    availableLikes: false,
                    availableComments: false,
                    availableShares: false,
                    availableViews: false,
                    availableInteractions: false,
                    activeDays: {},
                    latestPublishedAt: null
                };
            }

            var group = profilesByKey[key];
            if (!group.displayName && post && post.profile_display_name) {
                group.displayName = String(post.profile_display_name).trim();
            }
            if (!group.avatarUrl) {
                group.avatarUrl = getDrawerAvatarUrl(post);
            }
            if (!group.profileUrl) {
                group.profileUrl = safeDrawerUrl(post && post.profile_url);
            }
            if (!group.locationText && post && post.profile_location_text) {
                group.locationText = String(post.profile_location_text).trim();
            }
            if (!group.category && post && post.profile_category) {
                group.category = String(post.profile_category).trim();
            }
            if (group.isVerified !== true && drawerBoolean(post && post.profile_is_verified) === true) {
                group.isVerified = true;
            }

            [
                ['followers_count', 'followersCount'],
                ['following_count', 'followingCount'],
                ['profile_posts_count', 'profilePostsCount']
            ].forEach(function(mapping) {
                var value = drawerNumber(post && post[mapping[0]]);
                if (value !== null) {
                    group[mapping[1]] = value;
                }
            });

            group.posts += 1;

            [
                ['likes_count', 'likes', 'availableLikes'],
                ['platform_comments_count', 'comments', 'availableComments'],
                ['shares_count', 'shares', 'availableShares'],
                ['views_count', 'views', 'availableViews']
            ].forEach(function(mapping) {
                var value = drawerNumber(post && post[mapping[0]]);
                if (value === null) {
                    return;
                }
                group[mapping[1]] += value;
                group[mapping[2]] = true;
            });

            var interactions = getDrawerInteractionTotal(post);
            if (interactions !== null) {
                group.interactions += interactions;
                group.availableInteractions = true;
            }

            if (post && post.published_at) {
                var published = new Date(post.published_at);
                if (!isNaN(published.getTime())) {
                    var dayKey = published.toISOString().slice(0, 10);
                    group.activeDays[dayKey] = true;
                    if (!group.latestPublishedAt || published.getTime() > new Date(group.latestPublishedAt).getTime()) {
                        group.latestPublishedAt = published.toISOString();
                    }
                }
            }
        });

        return Object.keys(profilesByKey)
            .map(function(key) {
                var group = profilesByKey[key];
                group.activeDayCount = Object.keys(group.activeDays).length;
                group.postsPerActiveDay = group.activeDayCount ? group.posts / group.activeDayCount : null;
                return group;
            })
            .sort(function(a, b) {
                return b.posts - a.posts ||
                    (b.availableInteractions ? b.interactions : -1) -
                    (a.availableInteractions ? a.interactions : -1);
            });
    }


    function getDrawerActorStats(actors) {
