    function getDrawerCorpusPosts(posts, actors) {
        var corpus = [];

        asArray(posts).forEach(function(post) {
            corpus.push({
                content_text: post && post.content_text || ''
            });
        });

        asArray(actors).forEach(function(actor) {
            corpus.push({
                content_text: actor && actor.content_text || ''
            });
        });

        return corpus;
    }

    function getDrawerRelations(posts, actors) {
        var corpus = getDrawerCorpusPosts(posts, actors);
        var terms = getDrawerTerms(corpus).terms.slice(0, 14);
        var allowed = {};
        var labels = {};

        terms.forEach(function(item) {
            var key = normalizeDrawerWord(item.label);
            allowed[key] = true;
            labels[key] = item.label;
        });

        var pairs = {};

        corpus.forEach(function(item) {
            var normalized = normalizeDrawerWord(item && item.content_text || '')
                .replace(/https?:\/\/\S+/g, ' ')
                .replace(/[^a-z0-9ñ#]+/g, ' ');

            var present = {};

            normalized.split(/\s+/).forEach(function(word) {
                if (allowed[word]) {
                    present[word] = true;
                }
            });

            var keys = Object.keys(present).sort();

            for (var i = 0; i < keys.length; i += 1) {
                for (var j = i + 1; j < keys.length; j += 1) {
                    var pairKey = keys[i] + '||' + keys[j];
                    pairs[pairKey] = (pairs[pairKey] || 0) + 1;
                }
            }
        });

        return Object.keys(pairs)
            .map(function(key) {
                var parts = key.split('||');
                return {
                    source: labels[parts[0]] || parts[0],
                    target: labels[parts[1]] || parts[1],
                    label: (labels[parts[0]] || parts[0]) + ' ↔ ' + (labels[parts[1]] || parts[1]),
                    count: pairs[key]
                };
            })
            .sort(function(a, b) {
                return b.count - a.count || a.label.localeCompare(b.label, 'es');
            })
            .slice(0, 18);
    }

    function getDrawerTimeline(posts, actors) {
        var timestamps = [];

        asArray(posts).forEach(function(post) {
            if (post && post.published_at) {
                var time = new Date(post.published_at).getTime();
                if (!isNaN(time)) {
                    timestamps.push(time);
                }
            }
        });

        asArray(actors).forEach(function(actor) {
            if (actor && actor.published_at) {
                var time = new Date(actor.published_at).getTime();
                if (!isNaN(time)) {
                    timestamps.push(time);
                }
            }
        });

        if (!timestamps.length) {
            return [];
        }

        var bounds = getDrawerRangeBounds();
        var start = bounds.start ? bounds.start.getTime() : Math.min.apply(null, timestamps);
        var end = bounds.end ? bounds.end.getTime() : Math.max.apply(null, timestamps);

        if (end < start) {
            var swap = start;
            start = end;
            end = swap;
        }

        var rangeMs = Math.max(1, end - start);
        var hourMs = 60 * 60 * 1000;
        var dayMs = 24 * hourMs;
        var bucketMs = rangeMs <= 48 * hourMs ? hourMs : dayMs;

        start = Math.floor(start / bucketMs) * bucketMs;
        end = Math.ceil(end / bucketMs) * bucketMs;

        var maxBuckets = bucketMs === hourMs ? 49 : 45;
        var bucketCount = Math.floor((end - start) / bucketMs) + 1;

        if (bucketCount > maxBuckets) {
            bucketMs = Math.ceil((end - start) / (maxBuckets - 1));
            bucketMs = Math.max(dayMs, Math.ceil(bucketMs / dayMs) * dayMs);
            bucketCount = Math.floor((end - start) / bucketMs) + 1;
        }

        var buckets = [];

        for (var cursor = start; cursor <= end && buckets.length < maxBuckets; cursor += bucketMs) {
            var date = new Date(cursor);
            var label;

            try {
                if (bucketMs <= hourMs) {
                    label = new Intl.DateTimeFormat('es-MX', {
                        hour: 'numeric'
                    }).format(date);
                } else {
                    label = new Intl.DateTimeFormat('es-MX', {
                        day: '2-digit',
                        month: 'short'
                    }).format(date);
                }
            } catch (error) {
                label = date.toISOString();
            }

            buckets.push({
                start: cursor,
                end: cursor + bucketMs,
                label: label,
                publications: 0,
                actorEvents: 0,
                interactions: 0,
                views: 0
            });
        }

        function findBucket(time) {
            var index = Math.floor((time - start) / bucketMs);
            return index >= 0 && index < buckets.length ? buckets[index] : null;
        }

        asArray(posts).forEach(function(post) {
            if (!post || !post.published_at) {
                return;
            }

            var time = new Date(post.published_at).getTime();

            if (isNaN(time)) {
                return;
            }

            var bucket = findBucket(time);

            if (!bucket) {
                return;
            }

            bucket.publications += 1;

            var interactions = getDrawerInteractionTotal(post);
            if (interactions !== null) {
                bucket.interactions += interactions;
            }

            var views = drawerNumber(post.views_count);
            if (views !== null) {
                bucket.views += views;
            }
        });

        asArray(actors).forEach(function(actor) {
            if (!actor || !actor.published_at) {
                return;
            }

            var time = new Date(actor.published_at).getTime();

            if (isNaN(time)) {
                return;
            }

            var bucket = findBucket(time);

            if (bucket) {
                bucket.actorEvents += 1;
            }
        });

        return buckets;
    }

    function renderDrawerLineChart(timeline, series) {
        var data = asArray(timeline);
        var seriesList = asArray(series);

        if (!data.length || !seriesList.length) {
            return '<div class="drawer-empty-inline">Sin datos temporales disponibles.</div>';
        }

        var width = 760;
        var height = 250;
        var left = 42;
        var right = 12;
        var top = 14;
        var bottom = 34;
        var innerWidth = width - left - right;
        var innerHeight = height - top - bottom;
        var maxValue = 0;

        seriesList.forEach(function(item) {
            data.forEach(function(row) {
                var value = Number(row[item.key] || 0);
                if (isFinite(value) && value > maxValue) {
                    maxValue = value;
                }
            });
        });

        maxValue = Math.max(1, maxValue);

        var grid = '';
        for (var g = 0; g <= 4; g += 1) {
            var y = top + (innerHeight * g / 4);
            var value = maxValue * (1 - g / 4);
            grid +=
                '<line class="drawer-chart-grid" x1="' + left + '" y1="' + y.toFixed(2) + '" x2="' + (width - right) + '" y2="' + y.toFixed(2) + '"></line>' +
                '<text class="drawer-chart-axis-label" x="' + (left - 7) + '" y="' + (y + 3).toFixed(2) + '" text-anchor="end">' + escapeHtml(formatDrawerMetric(Math.round(value))) + '</text>';
        }

        var xLabels = '';
        var labelEvery = Math.max(1, Math.ceil(data.length / 8));

        data.forEach(function(row, index) {
            if (index % labelEvery !== 0 && index !== data.length - 1) {
                return;
            }
            var x = left + (data.length === 1 ? innerWidth / 2 : innerWidth * index / (data.length - 1));
            xLabels += '<text class="drawer-chart-axis-label" x="' + x.toFixed(2) + '" y="' + (height - 8) + '" text-anchor="middle">' + escapeHtml(row.label) + '</text>';
        });

        var paths = '';

        seriesList.forEach(function(item, seriesIndex) {
            var points = data.map(function(row, index) {
                var x = left + (data.length === 1 ? innerWidth / 2 : innerWidth * index / (data.length - 1));
                var value = Number(row[item.key] || 0);
                var y = top + innerHeight - (Math.max(0, value) / maxValue) * innerHeight;
                return {
                    x: x,
                    y: y
                };
            });

            var className = 'drawer-series-' + (seriesIndex + 1);

            paths += '<polyline class="drawer-chart-series ' + className + '" points="' +
                points.map(function(point) {
                    return point.x.toFixed(2) + ',' + point.y.toFixed(2);
                }).join(' ') +
                '"></polyline>';

            points.forEach(function(point) {
                paths += '<circle class="drawer-chart-dot ' + className + '" cx="' + point.x.toFixed(2) + '" cy="' + point.y.toFixed(2) + '" r="3.2"></circle>';
            });
        });

        var legend = '<div class="drawer-chart-legend">' +
            seriesList.map(function(item, index) {
                return '<span><i class="l' + (index + 1) + '"></i>' + escapeHtml(item.label) + '</span>';
            }).join('') +
            '</div>';

        return (
            '<svg class="drawer-line-chart" viewBox="0 0 ' + width + ' ' + height + '" role="img" aria-label="Línea de tiempo">' +
                grid +
                xLabels +
                paths +
            '</svg>' +
            legend
        );
    }

    function renderDrawerDonut(items) {
        var source = asArray(items).filter(function(item) {
            return Number(item.count !== undefined ? item.count : item.value || 0) > 0;
        });

        if (!source.length) {
            return '<div class="drawer-empty-inline">Sin datos disponibles.</div>';
        }

        var total = source.reduce(function(sum, item) {
            return sum + Number(item.count !== undefined ? item.count : item.value || 0);
        }, 0);

        var radius = 56;
        var circumference = 2 * Math.PI * radius;
        var offset = 0;

        var circles = source.slice(0, 5).map(function(item, index) {
            var value = Number(item.count !== undefined ? item.count : item.value || 0);
            var fraction = total ? value / total : 0;
            var dash = fraction * circumference;
            var gap = Math.max(0, circumference - dash);
            var circle =
                '<circle class="drawer-donut-segment drawer-series-' + ((index % 4) + 1) + '"' +
                    ' cx="70" cy="70" r="' + radius + '"' +
                    ' stroke-dasharray="' + dash.toFixed(3) + ' ' + gap.toFixed(3) + '"' +
                    ' stroke-dashoffset="' + (-offset).toFixed(3) + '">' +
                '</circle>';
            offset += dash;
            return circle;
        }).join('');

        var legend = source.slice(0, 5).map(function(item, index) {
            var value = Number(item.count !== undefined ? item.count : item.value || 0);
            var percent = total ? (value / total) * 100 : 0;
            return (
                '<div>' +
                    '<i class="l' + ((index % 4) + 1) + '" style="background:' +
                        (index % 4 === 0 ? 'var(--blue)' :
                         index % 4 === 1 ? 'var(--cyan)' :
                         index % 4 === 2 ? 'var(--warning)' :
                         'var(--light-blue)') +
                    '"></i>' +
                    '<span>' + escapeHtml(item.label || item.key || '') + '</span>' +
                    '<strong>' + escapeHtml(formatDrawerPercent(percent)) + '</strong>' +
                '</div>'
            );
        }).join('');

        return (
            '<div class="drawer-donut-wrap">' +
                '<svg class="drawer-donut-svg" viewBox="0 0 140 140" role="img" aria-label="Distribución">' +
                    '<circle class="drawer-donut-track" cx="70" cy="70" r="' + radius + '"></circle>' +
                    circles +
                '</svg>' +
                '<div class="drawer-donut-legend">' + legend + '</div>' +
            '</div>'
        );
    }

    function renderDrawerWordCloud(items) {
        var source = asArray(items);

        if (!source.length) {
            return '<div class="drawer-empty-inline">Sin términos disponibles.</div>';
        }

        var max = Math.max.apply(null, source.map(function(item) {
            return Number(item.count || 0);
        })) || 1;

        return (
            '<div class="drawer-word-cloud">' +
                source.slice(0, 42).map(function(item, index) {
                    var count = Number(item.count || 0);
                    var scale = count / max;
                    var size = 11 + scale * 20;
                    var colorClass = 'drawer-series-' + ((index % 4) + 1);

                    return (
                        '<span class="' + colorClass + '" style="font-size:' + size.toFixed(1) + 'px;color:' +
                            (index % 4 === 0 ? 'var(--blue-dark)' :
                             index % 4 === 1 ? 'var(--cyan)' :
                             index % 4 === 2 ? 'var(--warning)' :
                             'var(--ink-soft)') +
                            ';--cloud-duration:' + (4.4 + (index % 7) * 0.47).toFixed(2) + 's' +
                            ';--cloud-delay:-' + ((index % 9) * 0.31).toFixed(2) + 's' +
                            ';--cloud-rotate:' + (((index % 5) - 2) * 2.2).toFixed(1) + 'deg' +
                        '">' +
                            escapeHtml(item.label) +
                        '</span>'
                    );
                }).join('') +
            '</div>'
        );
    }

    function renderDrawerRelationNetwork(relations) {
        var source = asArray(relations).filter(function(item) {
            return item && item.source && item.target && Number(item.count || 0) > 0;
        }).slice(0, 16);

        if (!source.length) {
            return '<div class="drawer-empty-inline">No hay suficientes relaciones para construir el gráfico.</div>';
        }

        var nodeWeights = {};
        source.forEach(function(item) {
            nodeWeights[item.source] = (nodeWeights[item.source] || 0) + Number(item.count || 0);
            nodeWeights[item.target] = (nodeWeights[item.target] || 0) + Number(item.count || 0);
        });

        var nodeNames = Object.keys(nodeWeights)
            .sort(function(a, b) {
                return nodeWeights[b] - nodeWeights[a] || a.localeCompare(b, 'es');
            })
            .slice(0, 11);

        var allowed = {};
        nodeNames.forEach(function(name) { allowed[name] = true; });

        var edges = source.filter(function(item) {
            return allowed[item.source] && allowed[item.target];
        });

        var width = 760;
        var height = 390;
        var centerX = width / 2;
        var centerY = height / 2;
        var radiusX = 270;
        var radiusY = 132;
        var maxWeight = Math.max.apply(null, nodeNames.map(function(name) {
            return nodeWeights[name];
        })) || 1;
        var maxEdge = Math.max.apply(null, edges.map(function(item) {
            return Number(item.count || 0);
        })) || 1;

        var nodes = {};
        nodeNames.forEach(function(name, index) {
            var x;
            var y;
            if (index === 0) {
                x = centerX;
                y = centerY;
            } else {
                var angle = ((index - 1) / Math.max(1, nodeNames.length - 1)) * Math.PI * 2 - Math.PI / 2;
                x = centerX + Math.cos(angle) * radiusX;
                y = centerY + Math.sin(angle) * radiusY;
            }
            nodes[name] = { x: x, y: y, weight: nodeWeights[name] };
        });

        var edgeHtml = edges.map(function(item, index) {
            var a = nodes[item.source];
            var b = nodes[item.target];
            if (!a || !b) {
                return '';
            }
            var edgeCount = Number(item.count || 0);
            var strokeWidth = 1.2 + (edgeCount / maxEdge) * 4.2;
            return (
                '<g>' +
                    '<line class="drawer-relation-edge" x1="' + a.x.toFixed(2) + '" y1="' + a.y.toFixed(2) + '" x2="' + b.x.toFixed(2) + '" y2="' + b.y.toFixed(2) + '" style="stroke-width:' + strokeWidth.toFixed(2) + 'px;animation-delay:-' + ((index % 7) * .55).toFixed(2) + 's"></line>' +
                    '<text class="drawer-relation-count" x="' + ((a.x + b.x) / 2).toFixed(2) + '" y="' + (((a.y + b.y) / 2) - 4).toFixed(2) + '" text-anchor="middle">' + escapeHtml(formatDrawerMetric(edgeCount)) + '</text>' +
                '</g>'
            );
        }).join('');

        var nodeHtml = nodeNames.map(function(name, index) {
            var node = nodes[name];
            var scale = node.weight / maxWeight;
            var r = 19 + scale * 18;
            var label = name.length > 18 ? name.slice(0, 17) + '…' : name;
            return (
                '<g>' +
                    '<circle class="drawer-relation-node ' + (index === 0 ? 'primary' : '') + '" cx="' + node.x.toFixed(2) + '" cy="' + node.y.toFixed(2) + '" r="' + r.toFixed(2) + '" style="animation-delay:-' + ((index % 5) * .42).toFixed(2) + 's"></circle>' +
                    '<text class="drawer-relation-label" x="' + node.x.toFixed(2) + '" y="' + (node.y + 4).toFixed(2) + '" text-anchor="middle">' + escapeHtml(label) + '</text>' +
                '</g>'
            );
        }).join('');

        return (
            '<div class="drawer-relations-network">' +
                '<svg class="drawer-relations-svg" viewBox="0 0 ' + width + ' ' + height + '" role="img" aria-label="Red de relaciones entre términos">' +
                    edgeHtml +
                    nodeHtml +
                '</svg>' +
            '</div>'
        );
    }

    function renderDrawerGalleryCard(post) {
        var media = getDrawerMedia(post);
        var firstMedia = media.length ? media[0] : null;
        var mediaUrl = firstMedia ? safeDrawerUrl(firstMedia.media_url) : '';
        var previewUrl = firstMedia ? safeDrawerUrl(firstMedia.preview_url) : '';
        var mediaType = String(firstMedia && firstMedia.media_type || post && post.post_type || '').toLowerCase();
        var label = getDrawerProfileName(post);
        var mediaHtml = '<div class="drawer-gallery-media-empty">Sin media persistida</div>';

        if (mediaUrl || previewUrl) {
            if (mediaType === 'video' && mediaUrl) {
                mediaHtml =
                    '<video controls playsinline preload="metadata"' +
                        (previewUrl ? ' poster="' + escapeHtml(previewUrl) + '"' : '') +
                    '>' +
                        '<source src="' + escapeHtml(mediaUrl) + '">' +
                    '</video>';
            } else {
                mediaHtml =
                    '<img src="' + escapeHtml(previewUrl || mediaUrl) + '" alt="" loading="lazy" referrerpolicy="no-referrer">';
            }
        }

        return (
            '<article class="drawer-gallery-card">' +
                '<div class="drawer-gallery-copy">' +
                    '<div class="drawer-gallery-author">' +
                        renderDrawerAvatar(getDrawerAvatarUrl(post), label, 'drawer-avatar-sm') +
                        '<div>' +
                            '<strong>' + escapeHtml(label) + renderDrawerVerified(post && post.profile_is_verified) + '</strong>' +
                            '<span>' + escapeHtml(formatPlatformLabel(post && post.platform || '')) + ' · ' + escapeHtml(formatDrawerDateTime(post && post.published_at)) + '</span>' +
                        '</div>' +
                    '</div>' +
                    '<p>' + escapeHtml(post && post.content_text || 'Sin texto disponible.') + '</p>' +
                '</div>' +
                '<div class="drawer-gallery-media">' + mediaHtml + '</div>' +
            '</article>'
        );
    }

    function renderDrawerStatCard(label, value, detail) {
        return (
            '<article class="drawer-stat-card">' +
                '<span>' + escapeHtml(label) + '</span>' +
                '<strong>' + escapeHtml(value) + '</strong>' +
                (detail ? '<small>' + escapeHtml(detail) + '</small>' : '') +
            '</article>'
        );
    }

    function renderDrawerBarRows(items, options) {
        options = options || {};
        if (!items.length) {
            return '<div class="drawer-empty-inline">Sin datos disponibles.</div>';
        }
        var maxValue = Math.max.apply(null, items.map(function(item) {
            return Number(item.value !== undefined ? item.value : item.count || 0);
        })) || 1;

        return (
            '<div class="drawer-bar-list">' +
            items.map(function(item) {
                var raw = Number(item.value !== undefined ? item.value : item.count || 0);
                var width = Math.max(3, Math.min(100, (raw / maxValue) * 100));
                var formatted = options.formatValue ? options.formatValue(raw) : formatDrawerMetric(raw);
                return (
                    '<div class="drawer-bar-row">' +
                        '<div class="drawer-bar-row-head">' +
                            '<span>' + escapeHtml(item.label || item.key || '') + '</span>' +
                            '<strong>' + escapeHtml(formatted) + '</strong>' +
                        '</div>' +
                        '<div class="drawer-bar-track">' +
                            '<span class="drawer-bar-fill" style="width:' + escapeHtml(width.toFixed(2)) + '%"></span>' +
                        '</div>' +
                    '</div>'
                );
            }).join('') +
            '</div>'
        );
    }

    function renderDrawerChipCloud(items) {
        if (!items.length) {
            return '<div class="drawer-empty-inline">Sin datos disponibles.</div>';
        }
        return (
            '<div class="drawer-chip-cloud">' +
            items.map(function(item) {
                return (
                    '<span class="drawer-analysis-chip">' +
                        escapeHtml(item.label) +
                        '<strong>' + escapeHtml(item.count) + '</strong>' +
                    '</span>'
                );
            }).join('') +
            '</div>'
        );
    }

    function renderDrawerSectionShell(kicker, title, description, body) {
        return (
            '<div class="drawer-analysis-shell">' +
                '<header class="drawer-analysis-header">' +
                    '<div>' +
                        '<span class="drawer-analysis-kicker">' + escapeHtml(kicker) + '</span>' +
                        '<h3>' + escapeHtml(title) + '</h3>' +
                        '<p>' + escapeHtml(description) + '</p>' +
                    '</div>' +
                '</header>' +
                body +
            '</div>'
        );
    }

    function renderDrawerNoPosts(kicker, title) {
        return renderDrawerSectionShell(
            kicker,
            title,
            'No hay publicaciones coincidentes dentro del rango temporal seleccionado.',
            '<div class="drawer-analysis-empty">' +
                '<strong>Sin resultados en este rango</strong>' +
                '<span>Prueba 24 h, 7 d, 30 d o Todo.</span>' +
            '</div>'
        );
    }

    function renderDrawerWhatSection(posts, actors) {
        if (!posts.length && !actors.length) {
            return renderDrawerNoPosts('¿QUÉ?', 'Contenido y temáticas');
        }

        var corpus = getDrawerCorpusPosts(posts, actors);
        var terms = getDrawerTerms(corpus);
        var postTypes = getDrawerPostTypes(posts);
        var relations = getDrawerRelations(posts, actors);
        var activeTab = drawerState.whatTab || 'publications';

        var body = '';

        if (activeTab === 'themes') {
            body =
                '<div class="drawer-visual-grid">' +
                    '<section class="drawer-visual-card">' +
                        '<div class="drawer-visual-head"><div><strong>Tópicos</strong><span>Frecuencia en publicaciones y comentarios</span></div></div>' +
                        '<div class="drawer-visual-body">' +
                            renderDrawerWordCloud(terms.terms.concat(terms.hashtags).slice(0, 42)) +
                        '</div>' +
                    '</section>' +
                    '<section class="drawer-visual-card">' +
                        '<div class="drawer-visual-head"><div><strong>Tipo de contenido</strong><span>post_type persistido</span></div></div>' +
                        '<div class="drawer-visual-body">' + renderDrawerDonut(postTypes) + '</div>' +
                    '</section>' +
                '</div>' +
                '<div class="drawer-analysis-grid two" style="margin-top:12px">' +
                    '<section class="drawer-analysis-card">' +
                        '<div class="drawer-analysis-card-head"><strong>Temas de conversación</strong><span>Términos frecuentes</span></div>' +
                        renderDrawerBarRows(terms.terms.slice(0, 12)) +
                    '</section>' +
                    '<section class="drawer-analysis-card">' +
                        '<div class="drawer-analysis-card-head"><strong>Hashtags</strong><span>Frecuencia observada</span></div>' +
                        renderDrawerBarRows(terms.hashtags.slice(0, 12)) +
                    '</section>' +
                '</div>';
        } else if (activeTab === 'relations') {
            body =
                '<section class="drawer-analysis-card">' +
                    '<div class="drawer-analysis-card-head"><strong>Relaciones entre términos</strong><span>Red animada de coocurrencias dentro del mismo texto; no implica causalidad ni vínculo entre personas</span></div>' +
                    (relations.length
                        ? renderDrawerRelationNetwork(relations) +
                          '<div class="drawer-relations-list">' +
                            relations.slice(0, 12).map(function(item) {
                                return '<div class="drawer-relation-row"><span>' + escapeHtml(item.label) + '</span><strong>' + escapeHtml(formatDrawerMetric(item.count)) + '</strong></div>';
                            }).join('') +
                          '</div>'
                        : '<div class="drawer-empty-inline">No hay suficientes términos coincidentes para construir relaciones.</div>') +
                '</section>';
        } else {
            body =
                '<div class="drawer-gallery-grid">' +
                    posts.slice(0, 18).map(renderDrawerGalleryCard).join('') +
                '</div>' +
                (!posts.length
                    ? '<div class="drawer-analysis-empty"><strong>Sin publicaciones en el rango</strong><span>Los comentarios pueden existir, pero esta vista requiere publicaciones.</span></div>'
                    : '');
        }

        return renderDrawerSectionShell(
            '¿QUÉ?',
            'Publicaciones y temáticas',
            'Estructura visual basada en la referencia, utilizando únicamente publicaciones, comentarios y metadatos persistidos.',
            '<div class="drawer-subtabs">' +
                '<button type="button" class="drawer-subtab ' + (activeTab === 'publications' ? 'active' : '') + '" data-drawer-what-tab="publications">Publicaciones</button>' +
                '<button type="button" class="drawer-subtab ' + (activeTab === 'themes' ? 'active' : '') + '" data-drawer-what-tab="themes">Temáticas</button>' +
                '<button type="button" class="drawer-subtab ' + (activeTab === 'relations' ? 'active' : '') + '" data-drawer-what-tab="relations">Relaciones</button>' +
            '</div>' +
            body
        );
    }

    function getDrawerActorAvatar(actor, posts) {
        var directAvatar = safeDrawerUrl(
            actor && (
                actor.actorAvatarUrl ||
                actor.actor_avatar_url ||
                actor.avatar_url ||
                actor.profile_pic_url ||
                actor.profile_image_url
            )
        );

        if (directAvatar) {
            return directAvatar;
        }

        var actorName = normalizeDrawerWord(actor && actor.actorName || '');
        var actorUrl = safeDrawerUrl(actor && actor.actorUrl);
        var profiles = getDrawerProfiles(posts);

        for (var index = 0; index < profiles.length; index += 1) {
            var profile = profiles[index];
            var displayName = normalizeDrawerWord(profile.displayName || '');
            var handle = normalizeDrawerWord(String(profile.handle || '').replace(/^@/, ''));
            var profileUrl = safeDrawerUrl(profile.profileUrl);

            if (
                (actorUrl && profileUrl && actorUrl.replace(/\/$/, '') === profileUrl.replace(/\/$/, '')) ||
                (actorName && displayName && actorName === displayName) ||
                (actorName && handle && actorName === handle)
            ) {
                return profile.avatarUrl || '';
            }
        }

        return '';
    }

    function renderDrawerProfileMetricRows(profiles, valueGetter, detailGetter) {
        var source = asArray(profiles);
        if (!source.length) {
            return '<div class="drawer-empty-inline">Sin perfiles disponibles.</div>';
        }

        return (
            '<div class="drawer-profile-metric-list">' +
                source.map(function(profile) {
                    var label = profile.displayName || (profile.handle !== 'sin_handle' ? profile.handle.replace(/^@/, '') : formatPlatformLabel(profile.platform));
                    var value = valueGetter(profile);
                    var detail = detailGetter ? detailGetter(profile) : formatPlatformLabel(profile.platform);
                    return (
                        '<div class="drawer-profile-metric-row">' +
                            renderDrawerAvatar(profile.avatarUrl, label, 'drawer-avatar-sm') +
                            '<div class="drawer-profile-metric-main"><strong>' + escapeHtml(label) + '</strong><span>' + escapeHtml(detail) + '</span></div>' +
                            '<span class="drawer-profile-metric-value">' + escapeHtml(value) + '</span>' +
                        '</div>'
                    );
                }).join('') +
            '</div>'
        );
    }

    function renderDrawerWhenSection(posts, actors) {
        if (!posts.length && !actors.length) {
            return renderDrawerNoPosts('¿CUÁNDO?', 'Actividad en el tiempo');
        }

        var timeline = getDrawerTimeline(posts, actors);
        var actorStats = getDrawerActorStats(actors);
        var summary = getDrawerSummary(posts);
        var hourCounts = new Array(24).fill(0);

        posts.forEach(function(post) {
            if (!post || !post.published_at) {
                return;
            }
            var date = new Date(post.published_at);
            if (!isNaN(date.getTime())) {
                hourCounts[date.getHours()] += 1;
            }
        });

        actors.forEach(function(actor) {
            if (!actor || !actor.published_at) {
                return;
            }
            var date = new Date(actor.published_at);
            if (!isNaN(date.getTime())) {
                hourCounts[date.getHours()] += 1;
            }
        });

        var maxHour = Math.max.apply(null, hourCounts) || 1;
        var peakHour = 0;
        hourCounts.forEach(function(value, hour) {
            if (value > hourCounts[peakHour]) {
                peakHour = hour;
            }
        });

        var heatmap = '<div class="drawer-heatmap">' +
            hourCounts.map(function(value, hour) {
                var ratio = value / maxHour;
                var level = value === 0 ? 0 : ratio <= .25 ? 1 : ratio <= .5 ? 2 : ratio <= .75 ? 3 : 4;
                return '<span class="drawer-heat-cell" data-level="' + level + '" title="' + escapeHtml(String(hour).padStart(2, '0') + ':00 · ' + value + ' eventos') + '"></span>';
            }).join('') +
            '</div>' +
            '<div class="drawer-heat-labels"><span>0 h</span><span>6 h</span><span>12 h</span><span>23 h</span></div>';

        return renderDrawerSectionShell(
            '¿CUÁNDO?',
            'Actividad en el tiempo',
            'Distribución temporal calculada con published_at de publicaciones y comentarios/menciones del rango seleccionado.',
            '<div class="drawer-kpi-strip">' +
                '<article class="drawer-kpi-big"><span>Actores</span><strong>' + escapeHtml(formatDrawerMetric(actorStats.length)) + '</strong><small>comentaristas y fuentes únicas</small></article>' +
                '<article class="drawer-kpi-big"><span>Publicaciones</span><strong>' + escapeHtml(formatDrawerMetric(posts.length)) + '</strong><small>resultados en el rango</small></article>' +
                '<article class="drawer-kpi-big"><span>Comentarios / menciones</span><strong>' + escapeHtml(formatDrawerMetric(actors.length)) + '</strong><small>eventos persistidos</small></article>' +
                '<article class="drawer-kpi-big"><span>Interacciones</span><strong>' + escapeHtml(formatDrawerMetric(summary.interactions)) + '</strong><small>me gusta + comentarios + compartidos</small></article>' +
            '</div>' +
            '<section class="drawer-visual-card" style="margin-top:12px">' +
                '<div class="drawer-visual-head"><div><strong>Línea de tiempo</strong><span>Evolución por intervalo</span></div></div>' +
                '<div class="drawer-visual-body">' +
                    renderDrawerLineChart(timeline, [
                        { key: 'publications', label: 'Publicaciones' },
                        { key: 'actorEvents', label: 'Comentarios / menciones' },
                        { key: 'interactions', label: 'Interacciones' }
                    ]) +
                '</div>' +
            '</section>' +
            '<section class="drawer-analysis-card" style="margin-top:12px">' +
                '<div class="drawer-analysis-card-head"><strong>Actividad en el tiempo</strong><span>Momento pico: ' + escapeHtml(String(peakHour).padStart(2, '0') + ':00 · ' + formatDrawerMetric(hourCounts[peakHour]) + ' eventos') + '</span></div>' +
                heatmap +
            '</section>'
        );
    }

    function renderDrawerHowMuchSection(posts, actors) {
        if (!posts.length && !actors.length) {
            return renderDrawerNoPosts('¿CUÁNTO?', 'Volumen y alcance observado');
        }

        var summary = getDrawerSummary(posts);
        var profiles = getDrawerProfiles(posts);
        var actorStats = getDrawerActorStats(actors);

        var topProfiles = profiles.slice()
            .sort(function(a, b) {
                var viewA = a.availableViews ? a.views : -1;
                var viewB = b.availableViews ? b.views : -1;
                return viewB - viewA || b.posts - a.posts;
            })
            .slice(0, 10);

        return renderDrawerSectionShell(
            '¿CUÁNTO?',
            'Volumen y alcance observado',
            'La estructura sigue la referencia visual, sustituyendo audiencia estimada por métricas que sí están persistidas.',
            '<div class="drawer-analysis-grid two">' +
                '<article class="drawer-kpi-big"><span>Vistas registradas</span><strong>' + escapeHtml(formatDrawerMetric(summary.views)) + '</strong><small>Total disponible en views_count</small></article>' +
                '<article class="drawer-kpi-big"><span>Interacciones registradas</span><strong>' + escapeHtml(formatDrawerMetric(summary.interactions)) + '</strong><small>Me gusta + comentarios + compartidos</small></article>' +
            '</div>' +
            '<section class="drawer-analysis-card" style="margin-top:12px">' +
                '<div class="drawer-analysis-card-head"><strong>Top por volumen observado</strong><span>Perfiles de origen de las publicaciones</span></div>' +
                (topProfiles.length
                    ? '<div class="drawer-actor-ranking">' +
                        topProfiles.map(function(profile, index) {
                            var label = profile.displayName || (profile.handle !== 'sin_handle' ? profile.handle.replace(/^@/, '') : formatPlatformLabel(profile.platform));
                            var metric = profile.availableViews ? profile.views : (profile.availableInteractions ? profile.interactions : profile.posts);
                            var metricLabel = profile.availableViews ? 'vistas' : (profile.availableInteractions ? 'interacciones' : 'publicaciones');
                            return (
                                '<div class="drawer-actor-rank-row">' +
                                    '<span class="rank">' + escapeHtml(index + 1) + '</span>' +
                                    renderDrawerAvatar(profile.avatarUrl, label, 'drawer-avatar-sm') +
                                    '<div class="drawer-actor-rank-main"><strong>' + escapeHtml(label) + '</strong><span>' + escapeHtml(formatPlatformLabel(profile.platform)) + ' · ' + escapeHtml(metricLabel) + '</span></div>' +
                                    '<span class="drawer-actor-rank-count">' + escapeHtml(formatDrawerMetric(metric)) + '</span>' +
                                '</div>'
                            );
                        }).join('') +
                      '</div>'
                    : '<div class="drawer-empty-inline">Sin perfiles para ordenar.</div>') +
            '</section>' +
            '<section class="drawer-analysis-card" style="margin-top:12px">' +
                '<div class="drawer-analysis-card-head"><strong>Participación de actores</strong><span>Comentarios y menciones capturados</span></div>' +
                renderDrawerBarRows(actorStats.slice(0, 12).map(function(actor) {
                    return { label: actor.actorName, value: actor.events };
                })) +
            '</section>'
        );
    }

    function renderDrawerHowSection(posts, actors) {
        if (!posts.length && !actors.length) {
            return renderDrawerNoPosts('¿CÓMO?', 'Forma de interacción');
        }

        var summary = getDrawerSummary(posts);
        var timeline = getDrawerTimeline(posts, actors);
        var interactionItems = [
            { label: 'Me gusta', count: summary.likes === null ? 0 : summary.likes },
            { label: 'Comentarios', count: summary.comments === null ? 0 : summary.comments },
            { label: 'Compartidos', count: summary.shares === null ? 0 : summary.shares }
        ];

        return renderDrawerSectionShell(
            '¿CÓMO?',
            'Forma de interacción',
            'Diseño equivalente a la referencia de sentimiento, pero sin inventar polaridad: se representa la composición real de interacción y su evolución.',
            '<div class="drawer-how-grid">' +
                '<section class="drawer-visual-card">' +
                    '<div class="drawer-visual-head"><div><strong>Interacción</strong><span>Composición observada</span></div></div>' +
                    '<div class="drawer-visual-body">' +
                        renderDrawerDonut(interactionItems) +
                    '</div>' +
                '</section>' +
                '<section class="drawer-visual-card">' +
                    '<div class="drawer-visual-head"><div><strong>Interacción en el tiempo</strong><span>Publicaciones, comentarios/menciones e interacciones</span></div></div>' +
                    '<div class="drawer-visual-body">' +
                        renderDrawerLineChart(timeline, [
                            { key: 'publications', label: 'Publicaciones' },
                            { key: 'actorEvents', label: 'Comentarios / menciones' },
                            { key: 'interactions', label: 'Interacciones' }
                        ]) +
                    '</div>' +
                '</section>' +
            '</div>' +
            '<div class="drawer-analysis-note neutral" style="margin-top:12px">' +
