    function renderDrawerWhoSection(posts, actors) {
        if (!actors.length) {
            return renderDrawerSectionShell(
                '¿QUIÉN?',
                'Actores de la conversación',
                'Personas que comentan en redes sociales y fuentes que generan menciones web.',
                '<div class="drawer-analysis-empty"><strong>Sin actores en este rango</strong><span>Amplía el rango temporal para consultar comentarios o menciones persistidas.</span></div>'
            );
        }

        var actorStats = getDrawerActorStats(actors);
