        }).length;
        var socialComments = actors.length - webMentions;

        return renderDrawerSectionShell(
            '¿QUIÉN?',
            'Actores de la conversación',
            'Actores clave = autores de comentarios y fuentes de menciones web; no son los perfiles monitoreados.',
            '<div class="drawer-kpi-strip">' +
                '<article class="drawer-kpi-big"><span>Actores únicos</span><strong>' + escapeHtml(formatDrawerMetric(actorStats.length)) + '</strong><small>identidades observadas</small></article>' +
                '<article class="drawer-kpi-big"><span>Comentarios</span><strong>' + escapeHtml(formatDrawerMetric(socialComments)) + '</strong><small>eventos sociales</small></article>' +
                '<article class="drawer-kpi-big"><span>Menciones web</span><strong>' + escapeHtml(formatDrawerMetric(webMentions)) + '</strong><small>fuentes web</small></article>' +
                '<article class="drawer-kpi-big"><span>Actor más activo</span><strong>' + escapeHtml(actorStats[0] ? formatDrawerMetric(actorStats[0].events) : '—') + '</strong><small>' + escapeHtml(actorStats[0] ? actorStats[0].actorName : 'Sin actor') + '</small></article>' +
            '</div>' +
            '<div class="drawer-analysis-grid two" style="margin-top:12px">' +
                '<section class="drawer-analysis-card">' +
                    '<div class="drawer-analysis-card-head"><strong>Actores clave</strong><span>Ordenados por comentarios y menciones</span></div>' +
                    '<div class="drawer-actor-ranking">' +
                        actorStats.slice(0, 20).map(function(actor, index) {
                            return (
                                '<div class="drawer-actor-rank-row">' +
                                    '<span class="rank">' + escapeHtml(index + 1) + '</span>' +
                                    renderDrawerAvatar(getDrawerActorAvatar(actor, posts), actor.actorName, 'drawer-avatar-sm') +
                                    '<div class="drawer-actor-rank-main"><strong>' + escapeHtml(actor.actorName) + '</strong><span>' + escapeHtml(formatPlatformLabel(actor.platform)) + (actor.actorGender ? ' · ' + escapeHtml(actor.actorGender) : '') + '</span></div>' +
                                    '<span class="drawer-actor-rank-count">' + escapeHtml(formatDrawerMetric(actor.events)) + '</span>' +
