                        }).join('') +
                    '</div>' +
                '</section>' +
                '<section class="drawer-analysis-card">' +
                    '<div class="drawer-analysis-card-head"><strong>Género declarado / clasificado</strong><span>Valor persistido en author_gender; no se infiere en la interfaz</span></div>' +
                    '<div class="drawer-gender-grid">' +
                        genders.map(function(item) {
                            return '<article class="drawer-gender-card"><span>' + escapeHtml(item.label) + '</span><strong>' + escapeHtml(formatDrawerMetric(item.count)) + '</strong></article>';
                        }).join('') +
                    '</div>' +
                '</section>' +
            '</div>'
        );
    }

    function renderDrawerWhereSection(posts) {
        if (!posts.length) {
            return renderDrawerNoPosts('¿DÓNDE?', 'Origen y ubicación explícita');
        }
        var platformCounts = getDrawerPlatformCounts(posts).map(function(item) {
            return { label: formatPlatformLabel(item.platform), value: item.count };
        });
        var profiles = getDrawerProfiles(posts);
        var locatedProfiles = profiles.filter(function(profile) {
            return Boolean(profile.locationText);
        });

        return renderDrawerSectionShell(
            '¿DÓNDE?',
            'Origen y ubicación explícita',
