    function renderDrawerMedia(post) {
        var media = getDrawerMedia(post);
        if (!media.length) {
            return '';
        }

        return (
            '<div class="query-drawer-post-media">' +
                '<div class="query-drawer-media-strip">' +
                media.map(function(item, index) {
                    var mediaType = String(item.media_type || '').trim().toLowerCase();
                    var mediaUrl = safeDrawerUrl(item.media_url);
                    var previewUrl = safeDrawerUrl(item.preview_url);
                    var visual = '';

                    if (mediaType === 'video' && mediaUrl) {
                        visual =
                            '<video class="query-drawer-media-video" controls playsinline preload="metadata"' +
                                (previewUrl ? ' poster="' + escapeHtml(previewUrl) + '"' : '') +
                            '>' +
                                '<source src="' + escapeHtml(mediaUrl) + '">' +
                            '</video>';
                    } else {
                        var imageUrl = mediaUrl || previewUrl;
                        if (imageUrl) {
                            visual = '<img class="query-drawer-media-image" src="' + escapeHtml(imageUrl) + '" alt="" loading="lazy" referrerpolicy="no-referrer">';
                        }
                    }

                    if (!visual) {
                        return '';
                    }

                    return (
                        '<div class="query-drawer-media-slide">' +
                            visual +
                            '<span class="query-drawer-media-type-badge">' +
                                escapeHtml(mediaType === 'video' ? '▶ Video' : mediaType === 'image' ? 'Imagen' : mediaType === 'carousel' ? 'Carrusel' : 'Media') +
                            '</span>' +
                            (media.length > 1
                                ? '<span class="query-drawer-carousel-badge">' + escapeHtml(String(index + 1) + ' / ' + String(media.length)) + '</span>'
                                : '') +
                        '</div>'
                    );
                }).join('') +
                '</div>' +
            '</div>'
        );
    }

