    function renderDrawerAnalysisSections(posts, actors, liveStreams) {
        var renderers = {
            what: function() { return renderDrawerWhatSection(posts, actors); },
            when: function() { return renderDrawerWhenSection(posts, actors); },
            howmuch: function() { return renderDrawerHowMuchSection(posts, actors); },
            how: function() { return renderDrawerHowSection(posts, actors); },
            who: function() { return renderDrawerWhoSection(posts, actors); },
            where: function() { return renderDrawerWhereSection(posts); },
            profiles: function() { return renderDrawerProfilesSection(posts, actors); },
            botometer: function() { return renderDrawerBotometerSection(posts); },
            streams: function() { return renderDrawerStreamsSection(posts, liveStreams); }
        };

        Object.keys(renderers).forEach(function(section) {
            var panel = document.querySelector('[data-drawer-section-panel="' + section + '"]');

            if (!panel) {
                return;
            }

            panel.innerHTML = renderers[section]();
        });
    }

    function renderQueryDrawer(model) {
        var drawerModel = model || getModel();
        var query = getSelectedQuery(drawerModel);
        var allPosts = getDrawerPosts(drawerModel);
        var allActors = getDrawerActors(drawerModel);
        var liveStreams = getDrawerLiveStreams(drawerModel);
        var posts = getFilteredDrawerPosts(allPosts);
        var actors = getFilteredDrawerActors(allActors);
        var feedPosts = getSortedDrawerPosts(posts);

        var titleElement = document.getElementById('queryDrawerTitle');
        var statusElement = document.getElementById('queryDrawerStatus');
        var formulaElement = document.getElementById('queryDrawerFormula');
        var countElement = document.getElementById('queryDrawerResultsCount');
        var observedElement = document.getElementById('queryDrawerObservedAt');
        var platformCountsElement = document.getElementById('queryDrawerPlatformCounts');
        var postsElement = document.getElementById('queryDrawerPosts');
        var feedCountElement = document.getElementById('queryDrawerFeedCount');

        if (titleElement) {
            titleElement.textContent =
                query && query.name
                    ? String(query.name)
                    : String(
                        drawerSelection.name ||
                        drawerModel.selectedQueryName ||
                        'Consulta'
                    );
        }

        if (statusElement) {
            var status = String(query && query.status || 'active').toLowerCase();
            statusElement.textContent = status === 'inactive' ? 'Inactiva' : 'Activa';
            statusElement.classList.toggle('inactive', status === 'inactive');
        }

        if (formulaElement) {
            formulaElement.textContent = String(query && query.formula_text || '');
        }

        updateDrawerRangeUi(posts);

        document.querySelectorAll('[data-drawer-feed-sort]').forEach(function(button) {
            button.classList.toggle('active', button.getAttribute('data-drawer-feed-sort') === drawerState.feedSort);
        });

        if (feedCountElement) {
            feedCountElement.textContent = String(posts.length) + (posts.length === 1 ? ' publicación' : ' publicaciones');
        }
        if (countElement) {
            countElement.textContent = String(posts.length);
        }
        if (observedElement) {
            observedElement.textContent = formatDrawerDateTime(getDrawerLatestObservedAt(posts));
        }

        if (platformCountsElement) {
            var counts = getDrawerPlatformCounts(posts);
            platformCountsElement.innerHTML = counts.length
                ? counts.map(function(item) {
                    return '<span class="query-drawer-platform-pill">' +
                        escapeHtml(formatPlatformLabel(item.platform)) + ' · ' + escapeHtml(item.count) +
                        '</span>';
                }).join('')
                : '<span class="query-drawer-platform-pill">Sin resultados</span>';
        }

        if (postsElement) {
            if (posts.length === 0) {
                var outsideRangeCount = Math.max(0, allPosts.length - posts.length);
                postsElement.innerHTML =
                    '<div class="query-drawer-empty">' +
                        '<span class="query-drawer-empty-icon">◉</span>' +
                        '<strong>Sin publicaciones en este rango</strong>' +
                        '<span>' +
                            (allPosts.length > 0
                                ? escapeHtml(formatDrawerMetric(outsideRangeCount) + ' publicación(es) existen fuera del rango actual. El filtro por defecto sigue siendo Últimas 12 horas.')
                                : 'La consulta no tiene publicaciones coincidentes disponibles.') +
                        '</span>' +
                        (allPosts.length > 0
                            ? '<div class="query-drawer-empty-actions">' +
                                '<button type="button" class="query-drawer-range-button" data-drawer-range="24h">Ver 24 h</button>' +
                                '<button type="button" class="query-drawer-range-button" data-drawer-range="all">Ver todo</button>' +
                              '</div>'
                            : '') +
                    '</div>';
            } else {
                postsElement.innerHTML = feedPosts.map(renderDrawerPost).join('');
            }
        }

        renderDrawerLiveSide(posts, actors);
        renderDrawerAnalysisSections(posts, actors, liveStreams);
        setDrawerSection(drawerState.activeSection || 'live');
    }

    function openQueryDrawer(query) {
        var overlay = document.getElementById('queryDrawerOverlay');
        if (!overlay) {
            return;
        }

        drawerState.open = true;
        drawerState.activeSection = 'live';

        if (query && query.id) {
            rememberDrawerSelection(
                query.id,
                query.name || '',
                query
            );
        }

        drawerState.range = '12h';
        drawerState.customStart = null;
        drawerState.customEnd = null;
        drawerState.feedSort = 'recent';
        drawerState.whatTab = 'publications';

        ensureDrawerRuntimeFixes();
        overlay.hidden = false;
        overlay.setAttribute('aria-hidden', 'false');
        initializeDrawerCustomRangeInputs();
        renderQueryDrawer();
        setDrawerSection('live');
        document.body.classList.add('query-drawer-open');

        requestAnimationFrame(function() {
            if (!drawerState.open) {
                return;
            }
            overlay.classList.add('open');
            var closeButton = overlay.querySelector('.query-drawer-close');
            if (closeButton) {
                closeButton.focus();
            }
        });
    }

    function closeQueryDrawer() {
        var overlay = document.getElementById('queryDrawerOverlay');
        if (!overlay || !drawerState.open) {
            return;
        }

        drawerState.open = false;
        overlay.classList.remove('open');
        overlay.setAttribute('aria-hidden', 'true');
        document.body.classList.remove('query-drawer-open');

        setTimeout(function() {
            if (!drawerState.open) {
                overlay.hidden = true;
            }
        }, 260);
    }

    async function selectSavedQuery(queryId) {
        var id = String(queryId || '').trim();
        if (!id) {
            return;
        }
        var query = getQueries().find(function(item) {
            return item && String(item.id || '') === id;
        });
        if (!query) {
            return;
        }

        var name = String(query.name || '');

        rememberDrawerSelection(
            id,
            name,
            query
        );

        lastSelectedQueryIdValue = id;

        await appsmith.updateModel({
            selectedQueryId: id,
            selectedQueryName: name
        });
        renderLibrary();
        openQueryDrawer(query);
        appsmith.triggerEvent('onSelectQuery', { queryId: id });
    }

    async function rerunSavedQuery(queryId) {
        var id = String(queryId || '').trim();
        if (!id) {
            return;
        }
        var query = getQueries().find(function(item) {
            return item && String(item.id || '') === id;
        });
        if (!query || query.use_web !== true) {
            return;
        }

        var name = String(query.name || '');
        lastSelectedQueryIdValue = id;
        await appsmith.updateModel({
            selectedQueryId: id,
            selectedQueryName: name
        });
        renderLibrary();
        appsmith.triggerEvent('onRerunQuery');
    }

    async function toggleSavedQueryStatus(queryId) {
        var id = String(queryId || '').trim();
        if (!id) {
            return;
        }
        var query = getQueries().find(function(item) {
            return item && String(item.id || '') === id;
        });
        if (!query) {
            return;
        }

        var name = String(query.name || '');
        lastSelectedQueryIdValue = id;
        await appsmith.updateModel({
            selectedQueryId: id,
            selectedQueryName: name
        });
        renderLibrary();
        appsmith.triggerEvent('onToggleQueryStatus');
    }


