    function renderModeSelector(mode) {
        var selector =
            document.getElementById(
                'constructorModeSelector'
            );

        if (!selector) {
            return;
        }

        if (mode === 'home') {
            selector.classList.remove(
                'visible'
            );

            return;
        }

        selector.classList.add(
            'visible'
        );

        var buttons =
            selector.querySelectorAll(
                '[data-mode]'
            );

        buttons.forEach(
            function(button) {
                var buttonMode =
                    button.getAttribute(
                        'data-mode'
                    );

                button.classList.toggle(
                    'active',
                    buttonMode === mode
