        var step1Title =
            document.getElementById(
                'wizardStep1Title'
            );

        var step1Subtitle =
            document.getElementById(
                'wizardStep1Subtitle'
            );

        var step2Title =
            document.getElementById(
                'wizardStep2Title'
            );

        var step2Subtitle =
            document.getElementById(
                'wizardStep2Subtitle'
            );

        if (
            !step1Title ||
