    function renderStepper(
        mode,
        step
    ) {
        var wizard =
            document.getElementById(
                'constructorWizard'
            );

        if (!wizard) {
            return;
        }

        if (mode === 'home') {
            wizard.hidden = true;
            return;
        }

        wizard.hidden = false;

        setWizardLabels(mode);

        var steps =
            wizard.querySelectorAll(
                '.wizard-step'
            );

        steps.forEach(
            function(stepElement) {
                var stepNumber =
                    parseInt(
                        stepElement.getAttribute(
                            'data-step'
                        ),
                        10
                    );

                stepElement.classList.toggle(
                    'active',
                    stepNumber === step
                );

                stepElement.classList.toggle(
                    'completed',
                    stepNumber < step
                );

                var numberElement =
                    stepElement.querySelector(
                        '.wizard-number'
                    );

                if (numberElement) {
                    numberElement.textContent =
                        stepNumber < step
                            ? '✓'
                            : String(
                                stepNumber
                            );
                }
            }
        );

        var lines =
            wizard.querySelectorAll(
                '.wizard-line'
            );

        lines.forEach(
            function(line, index) {
                line.classList.toggle(
                    'completed',
                    index + 1 < step
                );
            }
        );
    }

    function getOperatorTerms(
        group,
        operator
    ) {
        if (!group) {
            return [];
        }

        if (operator === 'include') {
            return group.include;
        }

        if (operator === 'and') {
            return group.and;
        }

        if (operator === 'and_not') {
            return group.and_not;
        }

        return [];
    }

    function getOperatorChipClass(
        operator
    ) {
        if (operator === 'and') {
            return 'and';
        }

        if (operator === 'and_not') {
            return 'exclude';
        }

        return '';
    }

    function getEmptyTermsText(
        operator
    ) {
        if (operator === 'include') {
            return (
                'Agrega al menos un término para este grupo.'
            );
        }

        if (operator === 'and') {
            return (
                'Sin condiciones obligatorias.'
            );
        }

        return 'Sin exclusiones.';
    }

    function renderTerms(
        group,
        operator
    ) {
        var terms =
            getOperatorTerms(
                group,
                operator
            );

        if (terms.length === 0) {
            return (
                '<span class="manual-empty-terms">' +
                    escapeHtml(
                        getEmptyTermsText(
                            operator
                        )
                    ) +
                '</span>'
            );
        }

        var chipClass =
            getOperatorChipClass(
                operator
            );

        return terms
            .map(
                function(term, index) {
                    return (
                        '<span class="manual-chip' +
                            (
                                chipClass
                                    ? ' ' +
                                        chipClass
                                    : ''
                            ) +
                        '">' +

                            '<span>' +
                                escapeHtml(
                                    term
                                ) +
                            '</span>' +

                            '<button' +
                                ' type="button"' +
                                ' class="manual-chip-remove"' +
                                ' data-remove-term="' +
                                    escapeHtml(
                                        operator
                                    ) +
                                '"' +
                                ' data-group-no="' +
                                    escapeHtml(
                                        group.group_no
                                    ) +
                                '"' +
                                ' data-term-index="' +
                                    escapeHtml(
                                        index
                                    ) +
                                '"' +
                                ' aria-label="Eliminar término"' +
                            '>' +
                                '×' +
                            '</button>' +

                        '</span>'
                    );
                }
            )
            .join('');
    }

    function renderRuleRow(
        group,
        operator
    ) {
        var badge = '';
        var badgeClass = '';
        var title = '';
        var description = '';
        var placeholder = '';

        if (operator === 'include') {
            badge = 'INCLUIR';
            badgeClass = 'include';
            title = 'Palabras o frases';
            description =
                'Basta con que aparezca uno de estos términos.';
            placeholder =
                'Añadir palabra o frase';
        }

        if (operator === 'and') {
            badge = 'AND';
            badgeClass = 'and';
            title =
                'También debe contener';
            description =
                'Condiciones que deben cumplirse simultáneamente.';
            placeholder =
                'Añadir condición obligatoria';
        }

        if (operator === 'and_not') {
            badge = 'AND NOT';
            badgeClass = 'exclude';
            title = 'Excluir';
            description =
                'Descarta resultados que contengan estos términos.';
            placeholder =
                'Añadir término a excluir';
        }

        return (
            '<div class="manual-rule-row">' +

                '<div class="manual-rule-copy">' +

                    '<span class="manual-rule-badge ' +
                        badgeClass +
                    '">' +
                        escapeHtml(
                            badge
                        ) +
                    '</span>' +

                    '<strong>' +
                        escapeHtml(
                            title
                        ) +
                    '</strong>' +

                    '<p>' +
                        escapeHtml(
                            description
                        ) +
                    '</p>' +

                '</div>' +

                '<div class="manual-rule-editor">' +

                    '<div class="manual-term-entry">' +

                        '<input' +
                            ' type="text"' +
                            ' class="manual-term-input"' +
                            ' data-term-input="' +
                                escapeHtml(
                                    operator
                                ) +
                            '"' +
                            ' data-group-no="' +
                                escapeHtml(
                                    group.group_no
                                ) +
                            '"' +
                            ' maxlength="500"' +
                            ' placeholder="' +
                                escapeHtml(
                                    placeholder
                                ) +
                            '"' +
                            ' autocomplete="off"' +
                        '>' +

                        '<button' +
                            ' type="button"' +
                            ' class="manual-add-term"' +
                            ' data-add-term="' +
                                escapeHtml(
                                    operator
                                ) +
                            '"' +
                            ' data-group-no="' +
                                escapeHtml(
                                    group.group_no
                                ) +
                            '"' +
                        '>' +
                            'Agregar' +
