        await appsmith.updateModel({
            constructor_mode:
                'home',

            constructor_step:
                0,

            query_name:
                '',

            query_status:
                'active',

            query_formula:
                '',

            query_use_web:
                false,

            query_groups_json:
                groupsJson,

            query_target_ids_json:
                idsJson,

            ai_instruction:
                '',

            ai_proposal_json:
                '{}',

            ai_explanation:
                '',

            ai_generated:
                false
        });

        renderCurrentView();
    }

    document.addEventListener(
        'submit',
        function(event) {
            if (
                event.target &&
                event.target.id ===
                'sourceForm'
            ) {
                event.preventDefault();

                createManagedSource();
            }
        }
    );

    document.addEventListener(
        'input',
        function(event) {
            if (
                event.target &&
                event.target.id ===
                'manualQueryName'
            ) {
                syncSaveForm();
            }

            if (
                event.target &&
                event.target.id ===
                'aiInstructionInput'
            ) {
                var aiButton =
                    document.getElementById(
                        'aiGenerateButton'
                    );

                var aiCounter =
                    document.getElementById(
                        'aiInstructionCounter'
                    );

                var aiRawText =
                    String(
                        event.target.value ||
                        ''
                    );

                var aiText =
                    aiRawText.trim();

                aiDraftInstruction =
                    aiRawText;

                if (aiCounter) {
                    aiCounter.textContent =
                        aiRawText.length +
                        ' / 1500' +
                        (
                            aiText.length < 20
                                ? ' · mínimo 20'
                                : ''
                        );
                }

                if (aiButton) {
                    aiButton.disabled =
                        aiRequestPending ||
                        aiText.length < 20 ||
                        aiRawText.length > 1500;
                }
            }

            if (
                event.target &&
                event.target.id ===
                'sourcesSearch'
            ) {
                scheduleSourceSearch(
                    event.target.value
                );
            }
        }
    );

    document.addEventListener(
        'change',
        function(event) {
            if (
                event.target &&
                event.target.classList &&
                event.target.classList.contains(
                    'query-drawer-tab-control'
                ) &&
                drawerState.open
            ) {
                var section =
                    String(
                        event.target.id ||
                        ''
                    ).replace(
                        'queryDrawerTab-',
                        ''
                    );

                setDrawerSection(
                    section
                );

                return;
            }

            if (
                event.target &&
                event.target.id ===
                'manualQueryStatus'
            ) {
                syncSaveForm();
            }

            if (
                event.target &&
                event.target.id ===
                'sourcePlatform'
            ) {
                syncSourceFormField(
                    'sourceFormPlatform',
                    event.target.value
                );
            }

            if (
                event.target &&
                event.target.id ===
                'sourceHandle'
            ) {
                syncSourceFormField(
                    'sourceFormHandle',
                    event.target.value
                );
            }

            if (
                event.target &&
                event.target.id ===
                'sourceExternalId'
            ) {
                syncSourceFormField(
                    'sourceFormExternalId',
                    event.target.value
                );
            }

            if (
                event.target &&
                event.target.id ===
                'sourcesPlatformFilter'
            ) {
                reloadSourcesWithPatch({
                    sourcePlatformFilter:
                        String(
                            event.target.value ||
                            ''
                        ).trim(),

                    sourcePage:
                        1
                });
            }

            if (
                event.target &&
                event.target.id ===
                'sourcesStatusFilter'
            ) {
                reloadSourcesWithPatch({
                    sourceStatusFilter:
                        String(
                            event.target.value ||
                            ''
                        ).trim(),

                    sourcePage:
                        1
                });
            }
        }
    );

    document.addEventListener(
        'keydown',
        function(event) {
            if (
                event.key === 'Escape' &&
                drawerState.open
            ) {
                event.preventDefault();
                closeQueryDrawer();
                return;
            }

            var queryCard =
                event.target.closest(
                    '[data-select-query-id]'
                );

            var interactiveControl =
                event.target.closest(
                    'button, input, select, textarea, a'
                );

            if (
                queryCard &&
                !interactiveControl &&
                (
                    event.key === 'Enter' ||
                    event.key === ' '
                )
            ) {
                event.preventDefault();

                selectSavedQuery(
                    queryCard.getAttribute(
                        'data-select-query-id'
                    )
                );

                return;
            }

            if (
                event.key !== 'Enter'
            ) {
                return;
            }

            if (
                event.target &&
                event.target.id ===
                'sourcesSearch'
            ) {
                event.preventDefault();

                if (sourceSearchTimer) {
                    clearTimeout(
                        sourceSearchTimer
                    );

                    sourceSearchTimer =
                        null;
                }

                reloadSourcesWithPatch({
                    sourceSearch:
                        String(
                            event.target.value ||
                            ''
                        ).trim(),

                    sourcePage:
                        1
                });

                return;
            }

            var input =
                event.target.closest(
                    '.manual-term-input[data-term-input]'
                );

            if (!input) {
                return;
            }

            event.preventDefault();

            var groupNo =
                input.getAttribute(
                    'data-group-no'
                );

            var operator =
                input.getAttribute(
                    'data-term-input'
                );

            var button =
                document.querySelector(
                    '.manual-add-term' +
                    '[data-group-no="' +
                    groupNo +
                    '"]' +
                    '[data-add-term="' +
                    operator +
                    '"]'
                );

            if (button) {
                addTerm(
                    button
                );
            }
        }
    );

    document.addEventListener(
        'click',
        function(event) {
            var drawerCloseButton =
                event.target.closest(
                    '[data-drawer-close]'
                );

            if (drawerCloseButton) {
                event.preventDefault();
                closeQueryDrawer();
                return;
            }

            var openPostButton =
                event.target.closest(
                    '[data-open-post-url]'
                );

            if (
                openPostButton &&
                drawerState.open
            ) {
                event.preventDefault();

                openPostExternally(
                    openPostButton.getAttribute(
                        'data-open-post-url'
                    )
                );

                return;
            }

            var drawerRangeButton =
                event.target.closest(
                    '[data-drawer-range]'
                );

            if (
                drawerRangeButton &&
                drawerState.open
            ) {
                event.preventDefault();

                var range =
                    String(
                        drawerRangeButton.getAttribute(
                            'data-drawer-range'
                        ) ||
                        ''
                    );

                var allowedRanges = [
                    '12h',
                    '24h',
                    '7d',
                    '30d',
                    'all',
                    'custom'
                ];

                if (
                    allowedRanges.indexOf(
                        range
                    ) !== -1
                ) {
                    drawerState.range =
                        range;

                    if (
                        range === 'custom'
                    ) {
                        initializeDrawerCustomRangeInputs();
                    }

                    renderQueryDrawer();
                }

                return;
            }

            var drawerCustomApply =
                event.target.closest(
                    '[data-drawer-custom-apply]'
                );

            if (
                drawerCustomApply &&
                drawerState.open
            ) {
                event.preventDefault();

                var startInput =
                    document.getElementById(
                        'queryDrawerRangeStart'
                    );

                var endInput =
                    document.getElementById(
                        'queryDrawerRangeEnd'
                    );

                var startValue =
                    startInput
                        ? String(
                            startInput.value ||
                            ''
                        )
                        : '';

                var endValue =
                    endInput
                        ? String(
                            endInput.value ||
                            ''
                        )
                        : '';

                var startDate =
                    startValue
                        ? new Date(
                            startValue
                        )
                        : null;

                var endDate =
                    endValue
                        ? new Date(
                            endValue
                        )
                        : null;

                if (
                    !startDate ||
                    !endDate ||
                    isNaN(
                        startDate.getTime()
                    ) ||
                    isNaN(
                        endDate.getTime()
                    ) ||
                    startDate.getTime() >
                        endDate.getTime()
                ) {
                    var caption =
                        document.getElementById(
                            'queryDrawerRangeCaption'
                        );

                    if (caption) {
                        caption.textContent =
                            'Revisa las fechas del rango';
                    }

                    return;
                }

                drawerState.range =
                    'custom';

                drawerState.customStart =
                    startDate.toISOString();

                drawerState.customEnd =
                    endDate.toISOString();

                renderQueryDrawer();

                return;
            }

            var drawerFeedSort =
                event.target.closest(
                    '[data-drawer-feed-sort]'
                );

            if (
                drawerFeedSort &&
                drawerState.open
            ) {
                event.preventDefault();

                var sort =
                    String(
                        drawerFeedSort.getAttribute(
                            'data-drawer-feed-sort'
                        ) ||
                        'recent'
                    );

                drawerState.feedSort =
                    sort === 'interaction'
                        ? 'interaction'
                        : 'recent';

                renderQueryDrawer();

                return;
            }

            var drawerWhatTab =
                event.target.closest(
                    '[data-drawer-what-tab]'
                );

            if (
                drawerWhatTab &&
                drawerState.open
            ) {
                event.preventDefault();

                var whatTab =
                    String(
                        drawerWhatTab.getAttribute(
                            'data-drawer-what-tab'
                        ) ||
                        'publications'
                    );

                drawerState.whatTab =
                    ['publications', 'themes', 'relations']
                        .indexOf(whatTab) !== -1
                            ? whatTab
                            : 'publications';

                renderQueryDrawer();

                return;
            }

            var queryViewButton =
                event.target.closest(
                    '[data-query-view]'
                );

            if (queryViewButton) {
                setQueryView(
                    queryViewButton.getAttribute(
                        'data-query-view'
                    )
                );

                return;
            }

            var createSourceButton =
                event.target.closest(
                    '#sourceCreateButton'
                );

            if (createSourceButton) {
                event.preventDefault();

                createManagedSource();

                return;
            }

            var toggleSourceButton =
                event.target.closest(
                    '[data-source-toggle-id]'
                );

            if (toggleSourceButton) {
                event.preventDefault();

                toggleManagedSource(
                    toggleSourceButton.getAttribute(
                        'data-source-toggle-id'
                    )
                );

                return;
            }

            var deleteSourceButton =
                event.target.closest(
                    '[data-source-delete-id]'
                );

            if (deleteSourceButton) {
                event.preventDefault();

                deleteManagedSource(
                    deleteSourceButton.getAttribute(
                        'data-source-delete-id'
                    )
                );

                return;
            }

            var previousSourcesButton =
                event.target.closest(
                    '#sourcesPrevPage'
                );

            if (previousSourcesButton) {
                event.preventDefault();

                changeSourcePage(
                    -1
                );

                return;
            }

            var nextSourcesButton =
                event.target.closest(
                    '#sourcesNextPage'
                );

            if (nextSourcesButton) {
                event.preventDefault();

                changeSourcePage(
                    1
                );

                return;
            }

            var generateAiButton =
                event.target.closest(
                    '[data-generate-ai]'
                );

            if (generateAiButton) {
                generateAiProposal();
                return;
            }

            var saveButton =
                event.target.closest(
                    '[data-save-query]'
                );

            if (saveButton) {
                saveManualQuery();
                return;
            }

            var sourceTarget =
                event.target.closest(
                    '[data-source-target-id]'
                );

            if (sourceTarget) {
                toggleTarget(
                    sourceTarget.getAttribute(
                        'data-source-target-id'
                    )
                );

                return;
            }

            var webSource =
                event.target.closest(
                    '[data-toggle-web]'
                );

            if (webSource) {
                toggleWeb();
                return;
            }

            var addTermButton =
                event.target.closest(
                    '[data-add-term]'
                );

            if (addTermButton) {
                addTerm(
                    addTermButton
                );

                return;
            }

            var removeTermButton =
                event.target.closest(
                    '[data-remove-term]'
                );

            if (removeTermButton) {
                removeTerm(
                    removeTermButton
                );

                return;
            }

            var addGroupButton =
                event.target.closest(
                    '[data-add-group]'
                );

            if (addGroupButton) {
                addGroup();
                return;
            }

            var nextStepButton =
                event.target.closest(
                    '[data-next-step]'
                );

            if (nextStepButton) {
                setStep(
                    nextStepButton.getAttribute(
                        'data-next-step'
                    )
                );

                return;
            }

            var prevStepButton =
                event.target.closest(
                    '[data-prev-step]'
                );

            if (prevStepButton) {
                setStep(
                    prevStepButton.getAttribute(
                        'data-prev-step'
                    )
                );

                return;
            }

            var homeButton =
                event.target.closest(
                    '[data-nav-home]'
                );

            if (homeButton) {
                resetConstructor();
                return;
            }

            var startModeButton =
                event.target.closest(
                    '[data-start-mode]'
                );

            if (startModeButton) {
                setMode(
                    startModeButton.getAttribute(
                        'data-start-mode'
                    )
                );

                return;
            }

            var modeButton =
                event.target.closest(
                    '[data-mode]'
                );

            if (modeButton) {
                setMode(
                    modeButton.getAttribute(
                        'data-mode'
                    )
                );

                return;
            }

            var newQueryButton =
                event.target.closest(
                    '#newQueryButton'
                );

            if (newQueryButton) {
                resetConstructor();
                return;
            }

            var toggleStatusButton =
                event.target.closest(
                    '[data-toggle-query-status-id]'
                );

            if (toggleStatusButton) {
                event.preventDefault();
                event.stopPropagation();

                toggleSavedQueryStatus(
                    toggleStatusButton.getAttribute(
                        'data-toggle-query-status-id'
                    )
                );

                return;
            }

            var rerunButton =
                event.target.closest(
                    '[data-rerun-query-id]'
                );

            if (rerunButton) {
                event.preventDefault();
                event.stopPropagation();

                rerunSavedQuery(
                    rerunButton.getAttribute(
                        'data-rerun-query-id'
                    )
                );

                return;
            }

            var queryCard =
                event.target.closest(
                    '[data-select-query-id]'
                );

            if (queryCard) {
                selectSavedQuery(
                    queryCard.getAttribute(
                        'data-select-query-id'
                    )
                );

                return;
            }

            var paginationButton =
                event.target.closest(
                    '[data-action]'
                );

            if (!paginationButton) {
                return;
            }

            var action =
                paginationButton.getAttribute(
                    'data-action'
                );

            if (
                action === 'prev-page'
            ) {
                if (
                    currentPage > 1
                ) {
                    currentPage -= 1;
                    renderLibrary();
                }

                return;
            }

            if (
                action === 'next-page'
            ) {
                var totalPages =
                    getTotalPages();

                if (
                    currentPage <
                    totalPages
                ) {
                    currentPage += 1;
                    renderLibrary();
                }
            }
        }
    );

    var initialMode =
        String(
            getModel()
                .constructor_mode ||
            'home'
        )
        .trim()
        .toLowerCase();

    currentMode =
        initialMode === 'manual' ||
        initialMode === 'ai'
            ? initialMode
            : 'home';

    var initialStep =
        parseInt(
            getModel()
                .constructor_step ||
            0,
            10
        );

    currentStep =
        !isNaN(initialStep) &&
        initialStep >= 0 &&
        initialStep <= 4
            ? initialStep
            : 0;

    loadGroupsFromModel();
    loadSourcesFromModel();
    initializeSourceUiState(
        getModel()
    );

    renderLibrary();
    renderQueryNavigation();

    lastSourceManagementValue =
        getSourceManagementSignature(
            getModel()
        );

    lastQueriesValue =
        String(
            getModel().queries ||
            ''
        );

    lastTargetsValue =
        String(
            getModel().targets ||
            ''
        );

    lastModeValue =
        String(
            getModel()
                .constructor_mode ||
            'home'
        );

    lastStepValue =
        String(
            getModel()
                .constructor_step ||
            0
        );

    lastGroupsValue =
        String(
            getModel()
                .query_groups_json ||
            '[]'
        );

    lastTargetIdsValue =
        String(
            getModel()
                .query_target_ids_json ||
            '[]'
        );

    lastUseWebValue =
        String(
            getModel()
                .query_use_web ||
            false
        );

    lastAiResponseValue =
        String(
            getModel()
                .ai_response ||
            ''
        );

    lastSelectedQueryIdValue =
        String(
            getModel()
                .selectedQueryId ||
            ''
        );

    if (lastSelectedQueryIdValue.trim() !== '') {
        var initialSelectedQuery =
            asArray(
                getModel().queries
            )
            .find(function(item) {
                return (
                    item &&
                    String(item.id || '') ===
                        lastSelectedQueryIdValue.trim()
                );
            }) || null;

        rememberDrawerSelection(
            lastSelectedQueryIdValue,
            initialSelectedQuery &&
            initialSelectedQuery.name ||
            getModel().selectedQueryName ||
            '',
            initialSelectedQuery
        );
    }

    cacheDrawerPosts(
        getModel().drawerPosts
    );

    cacheDrawerActors(
        getModel().drawerActors
    );

    lastDrawerPostsValue =
        serializeDrawerPosts(
            getModel()
        );

    lastDrawerActorsValue =
        serializeDrawerActors(
            getModel()
        );

    if (
        typeof appsmith.onModelChange ===
        'function'
    ) {
        appsmith.onModelChange(
            function(newModel) {
                var model =
                    newModel ||
                    getModel();

                var queriesValue =
                    String(
                        model.queries ||
                        ''
                    );

                var targetsValue =
                    String(
                        model.targets ||
                        ''
                    );

                var modeValue =
                    String(
                        model
                            .constructor_mode ||
                        'home'
                    );

                var stepValue =
                    String(
                        model
                            .constructor_step ||
                        0
                    );

                var groupsValue =
                    String(
                        model
                            .query_groups_json ||
                        '[]'
                    );

                var targetIdsValue =
                    String(
                        model
                            .query_target_ids_json ||
                        '[]'
                    );

                var useWebValue =
                    String(
                        model
                            .query_use_web ||
                        false
                    );

                var aiResponseValue =
                    String(
                        model
                            .ai_response ||
                        ''
                    );

                var aiInstructionValue =
                    String(
                        model
                            .ai_instruction ||
                        ''
                    )
                    .trim();

                var selectedQueryIdValue =
                    String(
                        model
                            .selectedQueryId ||
                        ''
                    );

                if (selectedQueryIdValue.trim() !== '') {
                    var selectedQueryFromModel =
                        asArray(model.queries)
                            .find(function(item) {
                                return (
                                    item &&
                                    String(item.id || '') ===
                                        selectedQueryIdValue.trim()
                                );
                            }) || null;

                    rememberDrawerSelection(
                        selectedQueryIdValue,
                        selectedQueryFromModel &&
                        selectedQueryFromModel.name ||
                        model.selectedQueryName ||
                        drawerSelection.name,
                        selectedQueryFromModel
                    );
                }

                var incomingDrawerPosts =
                    asArray(
                        model.drawerPosts
                    );

                if (incomingDrawerPosts.length > 0) {
                    cacheDrawerPosts(
                        incomingDrawerPosts
                    );
                }

                var incomingDrawerActors =
                    asArray(
                        model.drawerActors
                    );

                if (incomingDrawerActors.length > 0) {
                    cacheDrawerActors(
                        incomingDrawerActors
                    );
                }

                var sourceManagementValue =
                    getSourceManagementSignature(
                        model
                    );

                var drawerPostsValue =
                    serializeDrawerPosts(
                        model
                    );

                var drawerActorsValue =
                    serializeDrawerActors(
                        model
                    );

                if (
                    aiGenerateArmed &&
                    aiRequestPending &&
                    getMode() === 'ai' &&
                    aiInstructionValue ===
                    aiGenerateInstruction
                ) {
                    aiGenerateArmed =
                        false;

                    appsmith.triggerEvent(
                        'onGenerateAI'
                    );
                }

                if (
                    queriesValue !==
                    lastQueriesValue
                ) {
                    var saveConfirmed =
                        false;

                    if (
                        pendingSaveConfirmation
                    ) {
                        var refreshedQueries =
                            asArray(
                                model.queries
                            );

                        saveConfirmed =
                            refreshedQueries.some(
                                function(query) {
                                    var queryId =
                                        String(
                                            query &&
                                            query.id ||
                                            ''
                                        ).trim();

                                    var queryName =
                                        String(
                                            query &&
                                            query.name ||
                                            ''
                                        ).trim();

                                    return (
                                        queryId !== '' &&
                                        queryName ===
                                            pendingSaveConfirmation
                                                .name &&
                                        pendingSaveConfirmation
                                            .existing_ids
                                            .indexOf(
                                                queryId
                                            ) === -1
                                    );
                                }
                            );
                    }

                    lastQueriesValue =
                        queriesValue;

                    currentPage =
                        1;

                    renderLibrary();

                    if (
                        saveConfirmed
                    ) {
                        pendingSaveConfirmation =
                            null;

                        resetConstructor();

                        return;
                    }
                }

                if (
                    selectedQueryIdValue !==
                    lastSelectedQueryIdValue
                ) {
                    lastSelectedQueryIdValue =
                        selectedQueryIdValue;

                    renderLibrary();

                    if (
                        drawerState.open
                    ) {
                        renderQueryDrawer(
                            model
                        );
                    }
                }

                if (
                    drawerPostsValue !==
                    lastDrawerPostsValue
                ) {
                    lastDrawerPostsValue =
                        drawerPostsValue;

                    if (
                        drawerState.open
                    ) {
                        renderQueryDrawer(
                            model
                        );
                    }
                }

                if (
                    drawerActorsValue !==
                    lastDrawerActorsValue
                ) {
                    lastDrawerActorsValue =
                        drawerActorsValue;

                    if (
                        drawerState.open
                    ) {
                        renderQueryDrawer(
                            model
                        );
                    }
                }

                if (
                    sourceManagementValue !==
                    lastSourceManagementValue
                ) {
                    lastSourceManagementValue =
                        sourceManagementValue;

                    if (
                        currentQueryView ===
                        'sources'
                    ) {
                        renderSourcesManagement(
                            model
                        );
                    }
                }

                if (
                    targetsValue !==
                    lastTargetsValue
                ) {
                    lastTargetsValue =
                        targetsValue;

                    if (
                        modeValue === 'manual' &&
                        (
                            stepValue === '2' ||
                            stepValue === '3' ||
                            stepValue === '4'
                        )
                    ) {
                        renderCurrentView();
                    }
                }

                if (
                    groupsValue !==
                    lastGroupsValue
                ) {
                    lastGroupsValue =
                        groupsValue;

                    loadGroupsFromModel();

                    if (
                        modeValue === 'manual' &&
                        (
                            stepValue === '1' ||
                            stepValue === '3' ||
                            stepValue === '4'
                        )
                    ) {
                        renderCurrentView();
                    }
                }

                if (
                    targetIdsValue !==
                        lastTargetIdsValue ||
                    useWebValue !==
                        lastUseWebValue
                ) {
                    lastTargetIdsValue =
                        targetIdsValue;

                    lastUseWebValue =
                        useWebValue;

                    loadSourcesFromModel();

                    if (
                        modeValue === 'manual' &&
                        (
                            stepValue === '2' ||
                            stepValue === '3' ||
                            stepValue === '4'
                        )
                    ) {
                        renderCurrentView();
                    }
                }

                if (
                    aiResponseValue !==
                    lastAiResponseValue
                ) {
                    lastAiResponseValue =
                        aiResponseValue;

                    if (
                        getMode() === 'ai'
                    ) {
                        var aiResponse =
                            asObject(
                                model.ai_response
                            );

                        if (
                            Object.keys(
                                aiResponse
                            ).length > 0 &&
                            (
                                aiResponse.ok === true ||
                                aiResponse
                                    .needs_clarification ===
                                    true
                            )
                        ) {
                            applyAiResponse(
                                aiResponse
                            );
                        }
                    }
                }

                if (
                    modeValue !==
                        lastModeValue ||
                    stepValue !==
                        lastStepValue
                ) {
                    lastModeValue =
                        modeValue;

                    lastStepValue =
                        stepValue;

                    renderCurrentView();
                }
            }
        );
    }
});
